  body String?

  /// Thread status (e.g. 'active', 'archived', 'hidden', 'pending') - Supports workflow in moderation and visibility per business rules.
  status String

  /// Whether the thread is pinned to the top - Implements requirement for important conversations to be highlighted by moderators/admins.
  is_pinned Boolean

