/**
 * Test creating a new configuration for the discussion board with unique and duplicate keys.
 *
 * This E2E test validates that an admin can successfully create a configuration record with all required fields, and that the system properly enforces uniqueness for config_key. It also asserts system rejection for missing required fields or invalid value_type, ensuring robust validation against schema and business rules.
 *
 * Steps:
 * 1. Create a configuration with valid config_key, config_value, value_type, and description.
 *    - Confirm successful creation (fields match input).
 * 2. Attempt to create another configuration with the same config_key.
 *    - Confirm the system rejects with an error (conflict or validation error).
 * 3. Attempt creation missing the required config_key field.
 *    - Expect schema validation failure.
 * 4. Attempt creation with an invalid value_type.
 *    - Expect server-side validation failure.
 */
export async function test_api_discussionboard_test_create_configuration_with_unique_and_duplicate_key(
  connection: api.IConnection,
