 *
 * - 존재하는 유효한 member history ID로 조회 시 정상적으로 상세 이벤트가 반영되어 반환되는지 검증한다.
 * - 존재하지 않거나 삭제된 UUID로 조회 시 404 오류가 반환되는지 확인한다.
 * - 권한 없는 역할(예: 인증 없는 사용자의 액세스)로 요청 시 403 Forbidden 에러가 발생하는지 검증한다.
 *
 * [테스트 시나리오]
 * 1. 신규 discussionboard 멤버를 생성한다.
 * 2. 해당 멤버의 member history 이벤트(임의 타입, 내용)를 신규 등록한다.
 * 3. 방금 생성된 member history id를 /discussionboard/memberHistories/{id}로 조회, 반환 값이 입력값과 일치하며 상세정보가 포함되는지 검사한다.
 * 4. 무작위 UUID(존재하지 않는 값)로 API를 호출, 404 오류(찾을 수 없음)가 나는지 확인한다.
 * 5. 인증/권한 없는 상태에서 동일 API 호출, 403 Forbidden이 정상 발생하는지 판단한다.
 */
export async function test_api_discussionboard_memberHistories_getById_existing_and_nonexisting(
  connection: api.IConnection,
) {
  // 1. 신규 discussionboard 멤버 생성
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. 멤버 이력 이벤트 생성
  const memberHistory = await api.functional.discussionboard.memberHistories.post(connection, {
    body: typia.random<IDiscussionboardMemberHistory.ICreate>()
  });
  typia.assert(memberHistory);

  // 3. 정상 조회
  const fetched = await api.functional.discussionboard.memberHistories.getById(connection, {
    id: memberHistory.id,
  });
  typia.assert(fetched);
  // 입력값과 반환값의 주요 항목 일치 확인(구체적 속성명 알 수 있으면 비교)
  // TestValidator.equals("이력 id 반환 일치")(fetched.id)(memberHistory.id);

  // 4. 존재하지 않는 id로 조회시 404
  await TestValidator.error("존재하지 않는 memberHistory id 조회시 404")(
    async () =>
      await api.functional.discussionboard.memberHistories.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      }),
  );

  // 5. 인증 없는 상태로 권한 검증(403)
  // headers를 정확히 IConnection 스펙에 맞게 복제하며 Authorization만 제거하여 비인가 상태를 구성
  const unauthenticated: api.IConnection = {
    ...connection,
    headers: Object.fromEntries(
      Object.entries(connection.headers ?? {}).filter(([k]) => k !== "Authorization")
    ),
  };
  await TestValidator.error("권한 없는 사용자의 memberHistory 조회 시 403")(
    async () =>
      await api.functional.discussionboard.memberHistories.getById(unauthenticated, {
        id: memberHistory.id,
      }),
  );
}

