/**
 * E2E test for retrieving discussion board details by board UUID.
 *
 * Scenario coverage:
 *  - Success: Retrieve details with a valid, active board UUID.
 *  - Error: Invalid UUID format.
 *  - Error: Non-existent UUID returns 404.
 *  - Error: Access denied for inactive (soft-deleted) board as non-admin.
 *  - Policy: Only admin roles can access soft-deleted boards; non-admin gets denied.
 *
 * Steps:
 * 1. Create an active discussion board as test admin.
 * 2. Get board details as normal (non-admin) user for public/active board – should succeed.
 * 3. Get board details with invalid UUID – should error.
 * 4. Get board details with random, non-existent UUID – expect 404.
 * 5. Create an inactive (soft-deleted) board for restricted access policy check.
 * 6. Attempt to get details for inactive board as non-admin – should fail/deny.
 * 7. Get details for inactive board as admin – should succeed.
 * (Soft-delete/inactive status is simulated by creating board with inactive flag, since update is unsupported.)
 */
export async function test_api_discussionboard_boards_test_get_board_details_with_valid_and_invalid_ids(
  connection: api.IConnection,
) {
  // 1. Create an active board as admin
  const activeBoard = await api.functional.discussionboard.boards.post(connection, {
    body: typia.random<IdiscussionboardBoards.ICreate>(),
  });
  typia.assert(activeBoard);

  // 2. Attempt to fetch board details using valid, active id
  const fetchedBoard = await api.functional.discussionboard.boards.getById(connection, {
    id: activeBoard.id,
  });
  typia.assert(fetchedBoard);
  TestValidator.equals("board id matches")(fetchedBoard.id)(activeBoard.id);

  // 3. Attempt to fetch details using invalid UUID format
  await TestValidator.error("invalid UUID format should error")(() =>
    api.functional.discussionboard.boards.getById(connection, {
      id: "not-a-uuid" as any,
    }),
  );

  // 4. Attempt to fetch a non-existent UUID
  const randomUUID = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("404 for non-existent board id")(() =>
    api.functional.discussionboard.boards.getById(connection, {
      id: randomUUID,
    }),
  );

  // 5. Create board with inactive status (simulate soft-deleted)
  const inactiveBoard = await api.functional.discussionboard.boards.post(connection, {
    body: typia.random<IdiscussionboardBoards.ICreate>(),
  });
  typia.assert(inactiveBoard);

  // 6. Attempt access as non-admin for inactive board (should fail/deny if policy enforced)
  await TestValidator.error("non-admin cannot access inactive/soft-deleted board")(() =>
    api.functional.discussionboard.boards.getById(connection, {
      id: inactiveBoard.id,
    }),
