/**
 * 플랫폼 관리자 소프트 딜리트(삭제) API 종합 검증
 *
 * 이 테스트는 관리자 계정 소프트 삭제(soft-delete) 기능에 대해 주요 케이스를 다음과 같이 검증합니다:
 *
 * 1. 서로 다른 2명의 새로운 관리자를 생성(A: privileged, B: target).
 * 2. 관리 A가 B를 삭제(soft-delete)하면, 응답과 deleted_at 필드 존재 및 변경을 검증합니다.
 * 3. 관리 A가 자신의 계정(본인 id) 삭제 시도를 하면 forbidden/권한실패(403 등)가 반환되는지 확인합니다.
 * 4. 무작위/존재하지 않는 UUID로 삭제 시도 시 404 등이 반환되는지 확인합니다.
 * 5. 관리자 권한이 없는 connection에서 삭제 시도 시 인증/권한 에러(401/403 등)가 발생하는지 검사합니다.
 * 6. 실제 감사 로그는 별도 조회 기능이 없어, deleted_at 값이 적절히 변화하는 것(soft-delete)으로 간접 검증합니다.
 *
 * 시험 순서는: 관리자 생성 → 소프트 딜리트 성공 케이스 → 각종 에러(본인 삭제, 미존재/권한 실패).
 */
export async function test_api_discussionboard_test_soft_delete_admin_by_id_with_audit_validation(
  connection: api.IConnection,
) {
  // 1. 관리자 A(삭제 수행자) 계정 생성
  const adminA = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(adminA);
  // 2. 관리자 B(삭제 대상자) 계정 생성
  const adminB = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
  typia.assert(adminB);

  // 3. A가 B 계정 삭제 시도(정상 케이스):
  const deleted = await api.functional.discussionboard.admins.eraseById(connection, {
    id: adminB.id,
  });
  typia.assert(deleted);
  // deleted_at 값 존재(soft-delete) 확인
  TestValidator.predicate("deleted_at must exist")(!!deleted.deleted_at);
  // id 동일
  TestValidator.equals("deleted id matches")(deleted.id)(adminB.id);

  // 4. 본인(A) 계정 본인 삭제 → forbidden/권한실패(error)
  await TestValidator.error("cannot delete own admin account")(
    async () => {
      await api.functional.discussionboard.admins.eraseById(connection, {
        id: adminA.id,
      });
    },
  );

  // 5. 임의의 무작위 UUID(존재하지 않는 id)로 삭제 시도 → 404 error
  await TestValidator.error("non-existent UUID returns 404")(
    async () => {
      await api.functional.discussionboard.admins.eraseById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 6. (권한 없는 connection) 비관리자 권한 상태로 삭제 시도 → 401/403
  // 권한없는 커넥션 모의: typia.random<IConnection>()로도 시도
  const anonymousConnection = typia.random<api.IConnection>();
  await TestValidator.error("non-admin connection forbidden")(
    async () => {
      await api.functional.discussionboard.admins.eraseById(anonymousConnection, {
        id: adminB.id,
      });
    },
  );
}

