import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardThreadFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadFollow";
import type { IPageDiscussionboardThreadFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardThreadFollow";

/**
 * Test filtered, paginated listing and permission checks for thread follow records in the discussion board.
 *
 * This end-to-end test validates several core behaviors:
 * - Regular members can only list thread follows where they themselves are the follower
 * - Filter/search/pagination parameters (memberId, threadId, follow date, etc) work and restrict results as intended
 * - The API never leaks follow information the actor does not own/cannot access
 * - Invalid input (malformed UUIDs, negative pagination) is rejected cleanly
 *
 * The test covers:
 * 1. Creation of two members
 * 2. Creation of two threads
 * 3. Both members following both threads in cross-pattern
 * 4. Listing as member 1: should only see their own follows, even if filters for other member/thread are used
 * 5. Listing as member 2: likewise only see own follows
 * 6. Pagination/filtering with real IDs
 * 7. Negative/invalid parameter inputs (bad uuid/negative page)
 */
export async function test_api_discussionboard_test_list_thread_follows_with_various_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. Create two members
  const member1 = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member2);

  // 2. Create two threads
  const thread1 = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread1);

  const thread2 = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread2);

  // 3. Both members follow both threads
  // Track follows for test assertions
  const followRecords: Array<{
    member: any; // Opaque, but store for referential filtering
    thread: any;
    record: any;
  }> = [];

  // Member 1 follows thread 1
  const follow11 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member1.id,
      threadId: thread1.id,
    },
  });
  typia.assert(follow11);
  followRecords.push({ member: member1, thread: thread1, record: follow11 });

  // Member 1 follows thread 2
  const follow12 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member1.id,
      threadId: thread2.id,
    },
  });
  typia.assert(follow12);
  followRecords.push({ member: member1, thread: thread2, record: follow12 });

  // Member 2 follows thread 1
  const follow21 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member2.id,
      threadId: thread1.id,
    },
  });
  typia.assert(follow21);
  followRecords.push({ member: member2, thread: thread1, record: follow21 });

  // Member 2 follows thread 2
  const follow22 = await api.functional.discussionboard.threadFollows.post(connection, {
    body: {
      ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
      memberId: member2.id,
      threadId: thread2.id,
    },
  });
  typia.assert(follow22);
  followRecords.push({ member: member2, thread: thread2, record: follow22 });

  // 4. As member 1, list follows (should only see their own)
  // (Simulation: connect as member1 if auth, otherwise just filter by id)
  const listAsMember1 = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member1.id,
      // No other filters: get all for member1
    } as any,
  });
  typia.assert(listAsMember1);
  for (const record of (listAsMember1.data?.records ?? [])) {
    if (record.memberId !== member1.id) {
      throw new Error("Member1 should only see their own follows");
    }
  }

  // 5. As member 2, likewise only see theirs
  const listAsMember2 = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member2.id,
    } as any,
  });
  typia.assert(listAsMember2);
  for (const record of (listAsMember2.data?.records ?? [])) {
    if (record.memberId !== member2.id) {
      throw new Error("Member2 should only see their own follows");
    }
  }

  // 6. Pagination/filter testing: get member1 follows, page 1, size 1
  const paged = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member1.id,
      page: 1,
      size: 1,
    } as any,
  });
  typia.assert(paged);
  if (!Array.isArray(paged.data?.records) || paged.data.records.length > 1) {
    throw new Error("Should only return at most one record on size 1 page");
  }

  // 7. Filtering by thread id for a member
  const filtered = await api.functional.discussionboard.threadFollows.patch(connection, {
    body: {
      memberId: member1.id,
      threadId: thread2.id,
    } as any,
  });
  typia.assert(filtered);
  for (const record of (filtered.data?.records ?? [])) {
    if (record.memberId !== member1.id || record.threadId !== thread2.id) {
      throw new Error("Filter by both member and thread must restrict to intersect");
    }
  }

  // 8. Negative/invalid inputs
  await TestValidator.error("bad uuid in memberId")(() =>
    api.functional.discussionboard.threadFollows.patch(connection, {
      body: {
        memberId: "not-a-uuid" as any,
      },
    }),
  );
  await TestValidator.error("negative page index")(() =>
    api.functional.discussionboard.threadFollows.patch(connection, {
      body: {
        memberId: member1.id,
        page: -1,
      },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardThreadFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadFollow";

/**
 * 스레드 팔로우 단일 조회 API의 소유자/권한 별 접근성 및 에러 시나리오 검증.
 *
 * - 본인 소유 팔로우 단일 조회 성공(권한 있음)
 * - 타 회원/관리자 접근 시 권한 제어(에러) (단, 로그인/권한 API 미제공 시 구현 불가)
 * - 존재하지 않는 id 조회 시 404 반환 검증
 *
 * [테스트 흐름 및 설명]
 * 1. 멤버A(팔로우 오너)와 멤버B(비오너) 회원을 생성한다.
 * 2. 멤버A가 신규 스레드를 생성한다.
 * 3. 멤버A가 해당 스레드를 팔로우한다.
 * 4. 멤버A의 인증 상태에서 팔로우 id로 단일 조회 API 호출 → 정상적으로 본인 팔로우 단일정보 반환됨을 검증.
 *   (실제 토큰 분기/로그인 전환 없으므로 한 커넥션 사용)
 * 5. (관리자/타 회원 권한 분기 검증: 로그인/권한 전환 API 없으므로 구현 생략)
 * 6. 존재하지 않는, 임의의 UUID(id)로 단일 조회 시 404/에러 반환됨 확인.
 */
export async function test_api_discussionboard_test_get_thread_follow_by_id_as_owner_and_as_admin(
  connection: api.IConnection,
) {
  // 1. 멤버A(오너/수행자)와 멤버B(비오너) 가입
  const memberACreate = typia.random<IDiscussionboardMember.ICreate>();
  const memberA = await api.functional.discussionboard.members.post(connection, { body: memberACreate });
  typia.assert(memberA);

  const memberBCreate = typia.random<IDiscussionboardMember.ICreate>();
  const memberB = await api.functional.discussionboard.members.post(connection, { body: memberBCreate });
  typia.assert(memberB);

  // 2. 멤버A가 스레드 생성
  const threadCreate = typia.random<IDiscussionboardThread.ICreate>();
  const thread = await api.functional.discussionboard.threads.post(connection, { body: threadCreate });
  typia.assert(thread);

  // 3. 멤버A가 해당 스레드를 팔로우
  const threadFollowCreate = typia.random<IDiscussionboardThreadFollow.ICreate>();
  const follow = await api.functional.discussionboard.threadFollows.post(connection, { body: threadFollowCreate });
  typia.assert(follow);

  // 4. 멤버A(오너/수행자)로 본인 팔로우 단일 조회
  const followById = await api.functional.discussionboard.threadFollows.getById(connection, { id: follow.id });
  typia.assert(followById);

  // 5. (타회원/관리자 권한 분기 접근 검증: 로그인/전환 API 미제공이므로 실제 구현 불가, 주석으로 안내 처리)

  // 6. 존재하지 않는 임의 id로 조회시 404/에러 발생 검증
  await TestValidator.error("존재하지 않는 팔로우 id 조회 404")(async () => {
    await api.functional.discussionboard.threadFollows.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardThreadFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadFollow";

/**
 * Test creating a new thread follow as a registered member and verify duplicate prevention.
 *
 * 1. Register a new discussion board member (user).
 * 2. Create a discussion thread as that member.
 * 3. As the member, follow the thread (should succeed).
 * 4. Attempt to follow the same thread again with the same member (should fail with 409 Conflict).
 * 5. Attempt to follow a non-existent thread (should fail with 404 Not Found).
 * 6. Attempt to follow as an unauthorized/unregistered user (should fail with 403 Forbidden).
 */
export async function test_api_discussionboard_test_create_thread_follow_success_and_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. Register a new member (user)
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create a discussion thread as that member
  const thread = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread);

  // 3. As the member, follow the thread (should succeed)
  const followParams = typia.random<IDiscussionboardThreadFollow.ICreate>();
  const follow = await api.functional.discussionboard.threadFollows.post(connection, {
    body: followParams,
  });
  typia.assert(follow);
  // If ID properties exist, you could check:
  // TestValidator.equals("thread id matches")(follow.threadId)(followParams.threadId);
  // TestValidator.equals("member id matches")(follow.memberId)(followParams.memberId);

  // 4. Attempt to follow the same thread again (should fail with 409 Conflict)
  await TestValidator.error("Duplicate thread follow should fail with 409")(() =>
    api.functional.discussionboard.threadFollows.post(connection, {
      body: followParams,
    })
  );

  // 5. Attempt to follow a non-existent thread (should fail with 404)
  const nonExistentFollowParams = {
    ...typia.random<IDiscussionboardThreadFollow.ICreate>(),
    threadId: "00000000-0000-0000-0000-000000000000",
  };
  await TestValidator.error("Follow on non-existent thread should fail with 404")(() =>
    api.functional.discussionboard.threadFollows.post(connection, {
      body: nonExistentFollowParams,
    })
  );

  // 6. Attempt to follow as unauthorized/unregistered user (should fail with 403)
  const unauthConnection = { ...connection, headers: {} };
  await TestValidator.error("Follow as unauthenticated user should fail with 403")(() =>
    api.functional.discussionboard.threadFollows.post(unauthConnection, {
      body: followParams,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardThreadFollow } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreadFollow";

/**
 * 토론 스레드 팔로우(threadFollow) 레코드의 알림/음소거 등 수정 가능한 필드 갱신 및 권한/존재성 검증
 *
 * - owner는 자신의 팔로우 레코드를 정상적으로 수정할 수 있고 결과가 반영됨을 검증
 * - nonOwner는 해당 팔로우 레코드에 대해 수정 시 Forbidden(권한 오류) 발생을 검증
 * - 임의의 존재하지 않는 팔로우 ID로 수정 시도 시 Not Found(404) 오류 발생을 검증
 *
 * [절차]
 * 1. 회원 2인(owner, nonOwner) 가입
 * 2. owner로 스레드 생성
 * 3. owner→thread follow 생성
 * 4. owner로 PUT: 팔로우 레코드(알림/음소거 등) 변경 후 결과 검증
 * 5. nonOwner로 동 레코드 putById 시도 → 권한 에러 확인
 * 6. 랜덤 uuid로 putById 시도 → 404 에러 확인
 */
export async function test_api_discussionboard_test_update_thread_follow_notification_settings_and_permissions(
  connection: api.IConnection,
) {
  // 1. 두 명의 회원 가입(owner, nonOwner)
  const ownerMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(ownerMember);

  const nonOwnerMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(nonOwnerMember);

  // 2. owner로 스레드 생성
  // (실제 Auth 헤더 등 멤버 구분 로직이 있으면 계정 전환 필요. 본 테스트 플랫폼 정책에 따라 구현)
  const thread = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread);

  // 3. owner로 thread follow 생성
  const threadFollow = await api.functional.discussionboard.threadFollows.post(connection, {
    body: typia.random<IDiscussionboardThreadFollow.ICreate>(),
  });
  typia.assert(threadFollow);

  // 4. owner가 자신의 팔로우 레코드의 알림/음소거 등 설정 필드 수정 시도
  const updateInput = typia.random<IDiscussionboardThreadFollow.IUpdate>();
  const updatedFollow = await api.functional.discussionboard.threadFollows.putById(connection, {
    id: threadFollow.id,
    body: updateInput,
  });
  typia.assert(updatedFollow);

  // 5. 수정 결과가 잘 반영됐는지(특정 mutable 필드 등)의 assert (구체 DTO 제공시 상세 검증 확장)
  // 예시: 알림 여부 등 필드가 있다면 아래와 같은 검증 추가 가능
  // TestValidator.equals('알림 설정')(updatedFollow.notificationEnabled)(updateInput.notificationEnabled);

  // 6. nonOwner가 동일 팔로우 레코드에 대해 putById 시도 시 권한 에러
  // (본 테스트 예시에서는 실제 인증/계정 전환 없이 진행 - 플랫폼의 인증 처리 특성에 따라 적절히 구현)
  TestValidator.error('팔로우 레코드 타 회원 수정 Forbidden')(() =>
    api.functional.discussionboard.threadFollows.putById(connection, {
      id: threadFollow.id,
      body: typia.random<IDiscussionboardThreadFollow.IUpdate>(),
    })
  );

  // 7. 존재하지 않는 랜덤 팔로우ID에 putById 시도 시 Not Found(404)
  TestValidator.error('존재하지 않는 팔로우ID putById → 404')(() =>
    api.functional.discussionboard.threadFollows.putById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: typia.random<IDiscussionboardThreadFollow.IUpdate>(),
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentEditHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentEditHistory";
import type { IPageIDiscussionboardCommentEditHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentEditHistory";

/**
 * Test retrieving a paginated list of comment edit histories with various filters.
 *
 * 1. Create several comments.
 * 2. Edit each comment multiple times as different (simulated) members to generate edit histories.
 * 3. Query edit histories filtered by specific comment ID, editor ID, and date ranges, verifying results only include correct histories.
 * 4. Test pagination by requesting specific pages and sizes with many histories.
 * 5. Confirm permission enforcement (placeholder, as real auth not integrated).
 * 6. Check edge cases: non-existent page (should return empty result) and validation error (invalid filter value triggers error).
 */
export async function test_api_discussionboard_test_list_comment_edit_histories_with_various_filters(connection: api.IConnection) {
  // 1. Create several comments
  const comments: any[] = [];
  for (let i = 0; i < 5; ++i) {
    const comment = await api.functional.discussionboard.comments.post(connection, {
      body: typia.random<IDiscussionboardComment.ICreate>(),
    });
    typia.assert(comment);
    comments.push(comment);
  }

  // 2. Edit each comment multiple times as different (simulated) members to create edit history
  for (const comment of comments) {
    for (let n = 0; n < 2; ++n) {
      const updated = await api.functional.discussionboard.comments.putById(connection, {
        id: comment.id,
        body: typia.random<IDiscussionboardComment.IUpdate>(),
      });
      typia.assert(updated);
    }
  }

  // 3. Query edit histories by commentId
  for (const comment of comments) {
    const filterByComment = await api.functional.discussionboard.commentEditHistories.patch(connection, {
      body: { comment_id: comment.id } satisfies IDiscussionboardCommentEditHistory.IRequest,
    });
    typia.assert(filterByComment);
  }

  // 4. Query with random filters including editor_id and time range
  const filterRequest = typia.random<IDiscussionboardCommentEditHistory.IRequest>();
  const filteredResult = await api.functional.discussionboard.commentEditHistories.patch(connection, {
    body: filterRequest,
  });
  typia.assert(filteredResult);

  // 5. Validation error: invalid filter value (e.g. invalid UUID)
  await TestValidator.error("invalid comment_id triggers error")(() =>
    api.functional.discussionboard.commentEditHistories.patch(connection, {
      body: { comment_id: "not-a-uuid" } satisfies IDiscussionboardCommentEditHistory.IRequest,
    })
  );

  // 6. Request a non-existent page (very large page number)
  const emptyResult = await api.functional.discussionboard.commentEditHistories.patch(connection, {
    body: { page: 9999, limit: 10 } satisfies IDiscussionboardCommentEditHistory.IRequest,
  });
  typia.assert(emptyResult);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentEditHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentEditHistory";
import type { IPageIDiscussionboardCommentEditHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentEditHistory";

/**
 * Test retrieving a specific discussion board comment edit history record by ID.
 *
 * This test verifies the life cycle of comment edit audit history:
 * 1. Create a comment
 * 2. Edit the comment (to trigger an edit audit record)
 * 3. List edit histories for the comment to obtain a real edit history ID
 * 4. Retrieve the history record by ID and check fields
 * 5. Attempt to fetch a bogus/non-existent or unauthorized record and expect error (404/403)
 *
 * Due to type=any for DTOs, deep property checks are impossible, but type- and ID-level threading can be confirmed.
 */
export async function test_api_discussionboard_test_get_comment_edit_history_by_id_existing_and_nonexistent(
  connection: api.IConnection,
) {
  // 1. Create a new comment
  const createdComment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(createdComment);

  // 2. Edit the comment to generate an edit history
  const editedComment = await api.functional.discussionboard.comments.putById(connection, {
    id: createdComment.id,
    body: typia.random<IDiscussionboardComment.IUpdate>(),
  });
  typia.assert(editedComment);

  // 3. List all edit histories for the comment
  const historiesPage = await api.functional.discussionboard.commentEditHistories.patch(connection, {
    body: { comment_id: createdComment.id } as any, // Filtering by comment (cannot check scheme, type=any)
  });
  typia.assert(historiesPage);

  // Should have at least one history (the just-made edit)
  if (!Array.isArray(historiesPage.data) || historiesPage.data.length === 0)
    throw new Error("No edit histories returned for updated comment");
  const historyItem = historiesPage.data[0];
  if (!historyItem?.id)
    throw new Error("First edit history record missing 'id' property");

  // 4. Retrieve the specific history record by its ID
  const retrieved = await api.functional.discussionboard.commentEditHistories.getById(connection, {
    id: historyItem.id,
  });
  typia.assert(retrieved);
  // Minimal cross-thread validation possible (opaque DTO): ID matches history list
  TestValidator.equals("edit history id")(retrieved.id)(historyItem.id);

  // 5. Attempt to retrieve a non-existent or unauthorized edit history record
  await TestValidator.error("should fail to get non-existent edit history")(
    () => api.functional.discussionboard.commentEditHistories.getById(connection, {
