  // 2. (성공케이스) 권한있는 사용자로 정상 삭제
  await api.functional.discussionboard.communityGuidelines.eraseById(connection, {
    id: guideline.id,
  });

  // 3. (실패케이스) 인증/권한 없는 connection으로 삭제 시도 시 오류 반환
  await TestValidator.error("unauthorized delete should fail")(
