  await TestValidator.error("delete non-existent guideline should fail")(
    () => api.functional.discussionboard.communityGuidelines.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
  await TestValidator.error("delete already-deleted guideline should fail")(
    () => api.functional.discussionboard.communityGuidelines.eraseById(connection, {
      id: guideline.id,
    })
  );
  // 5. (정책검증) 삭제 후 일반 접근이 불가함을 확인(감사/관리자 API 오딧 추가시 확장)
