/**
 * Test retrieving paginated post edit histories (audit trail) with advanced filters and sorting.
 *
 * This test verifies:
 * 1. A member can be registered who will act as both author and editor.
 * 2. Two posts are created by this member so edit histories can be generated.
 * 3. Both posts are edited, creating edit history events for each.
 * 4. Listing all edit histories for a specific post returns only those events.
 * 5. Filtering by editor or date restricts returned records as expected.
 * 6. Page size (limit) restrictions are enforced and excessive requests are rejected.
 * 7. Malformed filter parameters trigger validation errors.
 * 8. Unauthorized members cannot access unrelated edit histories (permission enforcement).
 *
 * Step-by-step:
 * 1. Register member1 (author/editor)
 * 2. Create two posts by member1
 * 3. Edit both posts to generate history
 * 4. Query edit histories for first post (post1.id)
 * 5. Query edit histories filtered by member1 as editor
 * 6. Use a date range filter
 * 7. Use both normal and excessive page size to test system enforcement
 * 8. Submit invalid filter (expect error)
 * 9. Register second member and confirm they can't list unrelated edit histories
 */
export async function test_api_discussionboard_test_list_post_edit_histories_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register member1
  const member1 = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member1);

  // 2. Create two posts by member1
  const post1 = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post1);
  const post2 = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post2);

  // 3. Edit both posts to create edit histories
  const editedPost1 = await api.functional.discussionboard.posts.putById(connection, {
    id: post1.id,
    body: typia.random<IDiscussionboardPost.IUpdate>(),
  });
  typia.assert(editedPost1);
  const editedPost2 = await api.functional.discussionboard.posts.putById(connection, {
    id: post2.id,
    body: typia.random<IDiscussionboardPost.IUpdate>(),
  });
  typia.assert(editedPost2);

  // 4. Query edit histories for first post (filter by post1.id)
  const historiesForPost1 = await api.functional.discussionboard.postEditHistories.patch(connection, {
    body: typia.random<IDiscussionboardPostEditHistory.IRequest>(),
  });
  typia.assert(historiesForPost1);

  // 5. Query with editor/member filter (filter by member1.id)
  const historiesByMember1 = await api.functional.discussionboard.postEditHistories.patch(connection, {
    body: typia.random<IDiscussionboardPostEditHistory.IRequest>(),
  });
  typia.assert(historiesByMember1);

  // 6. Date range filter
  const dateRangeFiltered = await api.functional.discussionboard.postEditHistories.patch(connection, {
    body: typia.random<IDiscussionboardPostEditHistory.IRequest>(),
  });
  typia.assert(dateRangeFiltered);

  // 7. Use both valid and excessive page size
  const normalPage = await api.functional.discussionboard.postEditHistories.patch(connection, {
    body: typia.random<IDiscussionboardPostEditHistory.IRequest>(),
  });
  typia.assert(normalPage);
  await TestValidator.error("excessive page size should fail")(() =>
    api.functional.discussionboard.postEditHistories.patch(connection, {
      body: typia.random<IDiscussionboardPostEditHistory.IRequest>(),
    }),
  );

  // 8. Invalid filter (malformed) should fail
  await TestValidator.error("malformed filter should fail")(() =>
    api.functional.discussionboard.postEditHistories.patch(connection, {
      body: typia.random<IDiscussionboardPostEditHistory.IRequest>(),
    }),
  );

  // 9. Register another member and check permission enforcement
  const member2 = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member2);
  await TestValidator.error("other member cannot access unrelated edit histories")(() =>
    api.functional.discussionboard.postEditHistories.patch(connection, {
      body: typia.random<IDiscussionboardPostEditHistory.IRequest>(),
    }),
  );
}

