import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IPageIDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardComment";

/**
 * Test retrieving a paginated, filtered list of comments from the discussion board.
 *
 * This test verifies:
 * 1. Filtering correctness by post ID, author ID, parent ID
 * 2. Pagination logic correctness
 * 3. Error handling for invalid query params
 *
 * Steps:
 * 1. Register several members (authors for comments)
 * 2. Create a post as the parent for comments
 * 3. Create a comment hierarchy (roots & replies, various authors)
 * 4. List/filter comments: by post, by author, by parent
 * 5. Paginate: page and size edge testing
 * 6. Pass an invalid parameter to trigger error handling (e.g., negative page)
 *
 * Notes: Permission/role-based visibility is omitted; SDK does not support it.
 */
export async function test_api_discussionboard_test_list_comments_with_various_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. Register members (authors for comments)
  const members: any[] = await Promise.all([
    api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() }),
    api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() }),
    api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() }),
  ]);
  for (const m of members) typia.assert(m);

  // 2. Create a post
  const post: any = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. Create root and reply comment structure
  const rootComments: any[] = await Promise.all([
    api.functional.discussionboard.comments.post(connection, {
      body: { ...typia.random<IDiscussionboardComment.ICreate>(), post_id: post.id, author_id: members[0].id, parent_id: null },
    }),
    api.functional.discussionboard.comments.post(connection, {
      body: { ...typia.random<IDiscussionboardComment.ICreate>(), post_id: post.id, author_id: members[1].id, parent_id: null },
    }),
  ]);
  for (const c of rootComments) typia.assert(c);

  const replies: any[] = await Promise.all([
    api.functional.discussionboard.comments.post(connection, { body: { ...typia.random<IDiscussionboardComment.ICreate>(), post_id: post.id, author_id: members[2].id, parent_id: rootComments[0].id } }),
    api.functional.discussionboard.comments.post(connection, { body: { ...typia.random<IDiscussionboardComment.ICreate>(), post_id: post.id, author_id: members[1].id, parent_id: rootComments[0].id } }),
    api.functional.discussionboard.comments.post(connection, { body: { ...typia.random<IDiscussionboardComment.ICreate>(), post_id: post.id, author_id: members[0].id, parent_id: rootComments[1].id } }),
  ]);
  for (const c of replies) typia.assert(c);

  // 4. List by post_id
  const byPostList: any = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id } as IDiscussionboardComment.IRequest,
  });
  typia.assert(byPostList);

  // 5. List by author_id
  const byAuthorList: any = await api.functional.discussionboard.comments.patch(connection, {
    body: { author_id: members[1].id } as IDiscussionboardComment.IRequest,
  });
  typia.assert(byAuthorList);
  if (byAuthorList && Array.isArray(byAuthorList.data)) {
    for (const c of byAuthorList.data) {
      TestValidator.equals("author match")(c.author_id)(members[1].id);
    }
  }

  // 6. List by parent_id (all replies to one root)
  const byParentList: any = await api.functional.discussionboard.comments.patch(connection, {
    body: { parent_id: rootComments[0].id } as IDiscussionboardComment.IRequest,
  });
  typia.assert(byParentList);
  if (byParentList && Array.isArray(byParentList.data)) {
    for (const c of byParentList.data) {
      TestValidator.equals("parent match")(c.parent_id)(rootComments[0].id);
    }
  }

  // 7. Pagination check (page/size)
  const pagedList1: any = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, page: 1, size: 2 } as IDiscussionboardComment.IRequest,
  });
  typia.assert(pagedList1);
  if (pagedList1 && Array.isArray(pagedList1.data)) {
    TestValidator.predicate("page1 limited")(pagedList1.data.length <= 2);
  }

  const pagedList2: any = await api.functional.discussionboard.comments.patch(connection, {
    body: { post_id: post.id, page: 2, size: 2 } as IDiscussionboardComment.IRequest,
  });
  typia.assert(pagedList2);
  if (
    pagedList1 && pagedList2 && Array.isArray(pagedList1.data) && Array.isArray(pagedList2.data) &&
    pagedList1.data.length > 0 && pagedList2.data.length > 0
  ) {
    const ids1: any[] = pagedList1.data.map((x: any) => x.id);
    const ids2: any[] = pagedList2.data.map((x: any) => x.id);
    TestValidator.predicate("no overlap")(ids1.every((id: any) => !ids2.includes(id)));
  }

  // 8. Invalid parameter error (negative page)
  await TestValidator.error("invalid page param")(async () => {
    await api.functional.discussionboard.comments.patch(connection, {
      body: { post_id: post.id, page: -1 } as IDiscussionboardComment.IRequest,
    });
  });
}

