/**
 * 토론 게시판 댓글 상세조회 API의 권한/에러/응답 필드 검증 통합 테스트
 *
 * 이 테스트는 다음의 시나리오를 종합적으로 검증한다:
 * 1. 서로 다른 권한(일반 회원, 모더레이터, 관리자)의 회원 3명을 각각 가입시킨다.
 * 2. (일반 회원) 댓글을 새로 작성한 뒤,
 * 3. 해당 댓글의 ID로 단일 상세를 정상적으로 조회한다.
 * 4. 존재하지 않는(유효 UUID) ID, 잘못된 형식의 ID(비-UUID)로 조회했을 때 오류를 반환하는지 확인한다.
 * 5. (삭제/flag 댓글 검증과 권한별 감춤/노출 정책은 별도 API/조작 미제공으로 실제 상태 조작/role 스위칭 검증은 skip)
 * 6. 응답 타입 내 audit, 부모/게시글 연관 필드가 정상 포함되는지 typia.assert로 확인한다.
 */
export async function test_api_discussionboard_test_get_comment_detail_with_permission_validation(
  connection: api.IConnection,
) {
  // 1. 멤버(일반/모더레이터/관리자) 계정 3명 생성
  const userMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(userMember);
  const moderatorMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(moderatorMember);
  const adminMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(adminMember);

  // 2. 일반 계정으로 댓글 작성
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment);

  // 3. 정상 댓글 상세 조회
  const detail = await api.functional.discussionboard.comments.getById(connection, {
    id: comment.id,
  });
  typia.assert(detail);
  TestValidator.equals("댓글 상세조회-아이디 일치")(detail.id)(comment.id);

  // 4. 존재하지 않는 ID(올바른 UUID 형식, 미존재) 케이스
  TestValidator.error("존재하지 않는 댓글 404")(async () => {
    await api.functional.discussionboard.comments.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 5. 잘못된 형식의 ID(비-UUID)
  TestValidator.error("잘못된 ID 포맷")(async () => {
    await api.functional.discussionboard.comments.getById(connection, {
      id: "invalid-id" as any,
    });
  });

  // 6. (권한별 삭제/flag 댓글: API/타입 미지원으로 실제 조작 skip, 필요시 detail 내 audit/flag 필드 타입검증만 가능)

  // 7. 응답 필드(연관 객체, 타임스탬프 등) 타입 어설션
  typia.assert(detail);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
