import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPolicy";

/**
 * 정책(Policy) 생성 API의 정상/비정상 및 권한별 검증 E2E 테스트
 *
 * 이 함수는 관리자 권한으로 정책을 정상적으로 생성하고,
 * 필수 입력값 누락, 중복 정책(동일 title/version), 잘못된 날짜(효력 개시/만료 순서 오류),
 * 비관리자 접근 등 다양한 실패(Validation, Permission) 케이스를 검증합니다.
 *
 * 검증 목표:
