 * - The channel must remain inaccessible to regular members after repeated deletions.
 *
 * Test Scenario Steps:
 * 1. Register a new admin (required for creating and deleting channels).
 * 2. Authenticate as the new admin (assume implicit via admin creation: no explicit login API available).
 * 3. Create a new discussion board channel as the admin.
 * 4. Soft-delete (erase) the channel as the admin.
 * 5. Attempt to soft-delete (erase) the same channel again as the admin:
 *    - Ensure no error is thrown (idempotency).
 *    - Confirm the returned entity/data is valid and unchanged in deleted status.
 *    - Optionally, assert that no duplicate side effects occur (cannot check audit log via API, so focus on functional API and data contract).
 * 6. (LIMITED) Since there is no member/member-access API or visibility assertion, we cannot directly verify member access is blocked. Rely on correct soft delete contract in returned object.
 */
export async function test_api_discussionboard_test_soft_delete_already_deleted_channel(
  connection: api.IConnection,
) {
  // 1. Create a new admin (required for all channel actions)
  const admin = await api.functional.discussionboard.admins.post(connection, {
    body: typia.random<IDiscussionboardAdmin.ICreate>(),
  });
