  // 2. Create a new channel as that admin
  const channel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channel);

  // 3. Soft-delete the channel (first deletion)
  const deleted = await api.functional.discussionboard.channels.eraseById(connection, {
    id: channel.id,
  });
  typia.assert(deleted);

  // 4. Attempt soft-delete again on the already-deleted channel (idempotency and error suppression)
  let repeatedDeletion: IDiscussionboardChannel | null = null;
  try {
    repeatedDeletion = await api.functional.discussionboard.channels.eraseById(connection, { id: channel.id });
    typia.assert(repeatedDeletion);
  } catch (err) {
    throw new Error("Repeated soft-delete should NOT throw a system error, but did: " + (err instanceof Error ? err.message : String(err)));
  }

  // 5. Confirm repeated deletion output is valid and matches 'deleted' state (actual structure unknown; idempotency focus)
  // Since returned DTO shape is opaque, we only verify its type and presence.
  TestValidator.predicate("Repeated deletion returns entity object")(typeof repeatedDeletion === "object" && !!repeatedDeletion);
}

