 *
 * 1. 관리자 권한으로 discussionboard 채널을 선행 생성한다.
 * 2. 해당 채널 하위에 고유한 이름, 설명, position, visible을 가진 섹션을 생성한다.
 * 3. 생성 응답 결과의 모든 필드를 검증한다.
 * 4. 동일 채널 내 동일 이름으로 중복 생성 시도 → 오류 확인
 * 5. 필수 필드(name) 누락 시 생성 실패를 검증 (TypeScript 타입상 불가이므로 실제 테스트는 skip)
 */
export async function test_api_discussionboard_test_create_section_success_with_valid_data(
  connection: api.IConnection,
) {
  // 1. 채널을 선행 생성 (관리자 권한)
  const channel = await api.functional.discussionboard.channels.post(connection, {
    body: typia.random<IDiscussionboardChannel.ICreate>(),
  });
  typia.assert(channel);

  // 2. 채널 하위 고유 이름 섹션 생성
  const uniqueName = `section-${Date.now()}-${Math.random().toString(36).substr(2, 8)}`;
  const sectionInput = {
    channel_id: channel.id,
    name: uniqueName,
    description: "E2E 테스트용 섹션 설명 ✨",
    position: 1,
    visible: true,
  } satisfies IDiscussionboardSection.ICreate;
  const section = await api.functional.discussionboard.sections.post(connection, {
    body: sectionInput,
  });
  typia.assert(section);
  TestValidator.equals("섹션 채널ID")(section.channel_id)(channel.id);
  TestValidator.equals("섹션 이름")(section.name)(uniqueName);
  TestValidator.equals("섹션 설명")(section.description)(sectionInput.description);
  TestValidator.equals("섹션 position")(section.position)(sectionInput.position);
  TestValidator.equals("섹션 visible")(section.visible)(sectionInput.visible);

  // 3. 동일 이름으로 중복 생성 시도 (같은 채널 내) → 비즈니스 제약 에러 검증
  await TestValidator.error("동일 채널 내 섹션명 중복 허용 안됨")(() =>
    api.functional.discussionboard.sections.post(connection, {
      body: { ...sectionInput },
