 * - 멤버 A가 같은 댓글에 중복 좋아요 시도 → 중복 에러
 * - 멤버 B가 동일 댓글 좋아요 → 정상
 * - 존재하지 않는 댓글로 좋아요 → 404/유효성 에러
 * - 미인증 사용자 좋아요 시도 → 인증 오류
 *
 * 각 단계가 정상 동작/실패하는지, 실제 관계형 데이터를 주입해 API 비즈니스 로직을 점검합니다.
 */
export async function test_api_discussionboard_test_create_comment_like_success_and_duplicate_prevention(
  connection: api.IConnection,
) {
  // 1. 멤버 A 생성
  const memberA = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberA);

  // 2. 멤버 A가 댓글 등록
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment);

  // 3. 멤버 A가 해당 댓글 좋아요 (정상)
  const likeA = await api.functional.discussionboard.commentLikes.post(connection, {
    body: {
      member_id: memberA.id,
      comment_id: comment.id,
    } satisfies IDiscussionboardCommentLike.ICreate,
  });
  typia.assert(likeA);

  // 4. 멤버 A가 동일 댓글에 중복 좋아요 (중복 에러)
  await TestValidator.error("같은 멤버-댓글 조합 중복 좋아요 불가")(
    async () => {
      await api.functional.discussionboard.commentLikes.post(connection, {
        body: {
          member_id: memberA.id,
          comment_id: comment.id,
        } satisfies IDiscussionboardCommentLike.ICreate,
      });
    },
  );

  // 5. 멤버 B 생성
  const memberB = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberB);

  // 6. 멤버 B가 같은 댓글 좋아요 (정상)
  const likeB = await api.functional.discussionboard.commentLikes.post(connection, {
    body: {
      member_id: memberB.id,
      comment_id: comment.id,
    } satisfies IDiscussionboardCommentLike.ICreate,
  });
  typia.assert(likeB);

  // 7. 존재하지 않는 댓글 id로 좋아요 → 에러
  await TestValidator.error("존재하지 않는 댓글 ID 좋아요 요청 오류")(
    async () => {
      await api.functional.discussionboard.commentLikes.post(connection, {
        body: {
          member_id: memberA.id,
          comment_id: typia.random<string>(),
        } satisfies IDiscussionboardCommentLike.ICreate,
      });
    },
  );

  // 8. 미인증 사용자의 좋아요 요청(인증 에러)
  const unauthConn = { ...connection, headers: {} };
  await TestValidator.error("인증 없는 좋아요 요청 오류")(
    async () => {
      await api.functional.discussionboard.commentLikes.post(unauthConn, {
        body: {
          member_id: memberA.id,
          comment_id: comment.id,
        } satisfies IDiscussionboardCommentLike.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentLike";

/**
 * Validate the update of modifiable metadata for a comment like record.
 *
 * This test covers rare admin/moderator operations, ensuring only permissible fields (such as updated_at or audit tags) can be modified via the update endpoint. It verifies that attempts to modify immutable or restricted fields—like changing comment linkage or member association—are rejected, and that updating comment likes as a non-admin is prohibited.
 *
 * Steps:
 * 1. Create two members: one admin and one regular.
 * 2. (As regular member) create a comment.
 * 3. (As regular member) like the comment.
 * 4. (As admin) update the like record with allowed metadata fields – assert update success, and verify type.
 * 5. (As admin) attempt to update immutable fields (e.g., comment linkage or member association) – assert error is thrown.
 * 6. (As regular member) attempt to update like record – assert error is thrown (permission denied).
 */
export async function test_api_discussionboard_test_update_comment_like_metadata_by_admin(
  connection: api.IConnection,
) {
  // 1. Create two members: one admin, one regular
  const adminMember = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(adminMember);
  const regularMember = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(regularMember);

  // 2. As the regular member, create a comment
  const comment = await api.functional.discussionboard.comments.post(connection, { body: typia.random<IDiscussionboardComment.ICreate>() });
  typia.assert(comment);

  // 3. As the regular member, like the comment
  const like = await api.functional.discussionboard.commentLikes.post(connection, { body: typia.random<IDiscussionboardCommentLike.ICreate>() });
  typia.assert(like);

  // 4. As the admin, update allowed metadata
  const updateBody = typia.random<IDiscussionboardCommentLike.IUpdate>();
  const updatedLike = await api.functional.discussionboard.commentLikes.putById(connection, { id: like.id, body: updateBody });
  typia.assert(updatedLike);

  // 5. As admin, attempt to update forbidden fields (simulate with common ids). Assert error.
  const forbiddenUpdate = { ...updateBody, comment_id: typia.random<string>(), member_id: typia.random<string>() };
  await TestValidator.error("admin forbidden update fields")(
    () => api.functional.discussionboard.commentLikes.putById(connection, { id: like.id, body: forbiddenUpdate })
  );

  // 6. As regular member, attempt update (permission denied expected)
  await TestValidator.error("regular cannot update like record")(
    () => api.functional.discussionboard.commentLikes.putById(connection, { id: like.id, body: updateBody })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentLike";

/**
 * Test unliking (deleting) a comment like record by its owner as well as by a moderator/admin.
 *
 * This test simulates a real-world scenario of unliking a comment, including various user roles and proper error handling:
 *
 * 1. Create three members: a 'liker', an 'unrelated' member, and an 'admin'.
 *    - Note: As there is no explicit concept of admin/moderator membership in the available API, all are just members. 'admin' is simulated as a regular member with the intention.
 * 2. Create a comment (can be owned by the liker).
 * 3. Like the comment as the liker (create a like record for the comment and member).
 * 4. Delete (unlike) the like as its owner (should succeed):
 *    - Assert that the delete API returns the like and that future deletion attempts fail (404).
 * 5. Re-like the comment as the liker to test permission checks again.
 * 6. Attempt to delete the like as the unrelated member (should fail):
 *    - Assert that an error is thrown.
 * 7. Delete the like as the simulated admin (should succeed):
 *    - Assert success and that repeated delete attempts fail.
 * 8. Confirm that attempting to delete an already deleted or non-existent like yields a 404 error.
 * 9. Skipped: Analytics/audit log validation (not feasible since no API is provided for this purpose).
 */
export async function test_api_discussionboard_test_delete_comment_like_by_owner_and_admin(
  connection: api.IConnection,
) {
  // 1. Create three members: liker, unrelated, admin
  const liker = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(liker);
  const unrelated = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(unrelated);
  const admin = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(admin);

  // 2. Create a comment by the liker
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment);

  // 3. Like the comment as the liker
  const origLike = await api.functional.discussionboard.commentLikes.post(connection, {
    body: typia.random<IDiscussionboardCommentLike.ICreate>(),
  });
  typia.assert(origLike);

  // 4. Delete the like as owner (should succeed)
  const deletedLike = await api.functional.discussionboard.commentLikes.eraseById(connection, {
    id: origLike.id,
  });
  typia.assert(deletedLike);

  // Try to delete again - should fail (simulate 404)
  await TestValidator.error("already deleted like cannot be deleted again")(
    async () => {
      await api.functional.discussionboard.commentLikes.eraseById(connection, {
        id: origLike.id,
      });
    },
  );

  // 5. Re-like for permission tests
  const relike = await api.functional.discussionboard.commentLikes.post(connection, {
    body: typia.random<IDiscussionboardCommentLike.ICreate>(),
  });
  typia.assert(relike);

  // 6. Attempt to delete as unrelated user (should fail)
  await TestValidator.error("unrelated member cannot delete another's like")(
    async () => {
      await api.functional.discussionboard.commentLikes.eraseById(connection, {
        id: relike.id,
      });
    },
  );

  // 7. Delete like as simulated admin (should succeed)
  const deletedByAdmin = await api.functional.discussionboard.commentLikes.eraseById(connection, {
    id: relike.id,
  });
  typia.assert(deletedByAdmin);

  // 8. Attempt to delete non-existent like (should get error)
  await TestValidator.error("cannot delete non-existent comment like")(
    async () => {
      await api.functional.discussionboard.commentLikes.eraseById(connection, {
        id: relike.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
