/**
 * 특정 게시글 좋아요를 ID로 조회하는 시나리오 검증
 *
 * 1. discussionboard_members POST로 게시글 작성자(author)와 좋아요 누를 멤버(liker) 등록
 * 2. author로 게시글 1개 생성
 * 3. liker 계정이 해당 게시글에 좋아요 생성 및 likeId 확보
 * 4. liker가 likeId로 단건 조회하면 post_id, member_id, created_at이 정확히 반환됨을 확인
 * 5. author로 계정 교체 후 동일 likeId GET 허용 여부 확인
 * 6. 별도의 3번째 멤버(unrelated)가 likeId 조회 시 권한 에러 발생 체크
 * 7. 존재하지 않는 likeId로 GET 시 404 에러 반환 확인
 */
export async function test_api_discussionboard_test_get_single_post_like_by_id_success(
  connection: api.IConnection,
) {
  // 1. 게시글 작성자 및 좋아요 누를 멤버 두 명 생성
  const author = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(author);
  const liker = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(liker);

  // 2. author 계정으로 게시글 1개 생성 (member_id 명시)
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: {
      ...typia.random<IDiscussionboardPost.ICreate>(),
      member_id: author.id,
    },
  });
  typia.assert(post);

  // 3. liker가 해당 게시글에 좋아요 생성
  const like = await api.functional.discussionboard.postLikes.post(connection, {
    body: {
      ...typia.random<Idiscussionboard_postLikes.ICreate>(),
      post_id: post.id,
      member_id: liker.id,
    },
  });
  typia.assert(like);

  // 4. liker 본인이 likeId로 GET시 정상 반환
  const likeByLiker = await api.functional.discussionboard.postLikes.getById(connection, {
    id: like.id,
  });
  typia.assert(likeByLiker);
  TestValidator.equals("post_id 동일")(likeByLiker.post_id)(post.id);
  TestValidator.equals("member_id 동일")(likeByLiker.member_id)(liker.id);
  TestValidator.predicate("created_at 존재")(!!likeByLiker.created_at);

  // 5. 게시글 작성자(author)로 동일 likeId GET이 허용되는지 검증
  const likeByAuthor = await api.functional.discussionboard.postLikes.getById(connection, {
    id: like.id,
  });
  typia.assert(likeByAuthor);
  TestValidator.equals("post_id 확인")(likeByAuthor.post_id)(post.id);

  // 6. 무관한 3번째 멤버(unrelated)가 likeId GET 시 권한 에러 확인
  const unrelated = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(unrelated);
  await TestValidator.error("무관 계정 권한 차단")(() =>
    api.functional.discussionboard.postLikes.getById(connection, { id: like.id }),
  );

  // 7. 존재하지 않는 likeId로 GET 시 404 확인
  await TestValidator.error("존재하지 않는 likeId 404")(() =>
    api.functional.discussionboard.postLikes.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
}

