 * - 게시글 존재여부, 중복 여부에 따라 정책적으로 실패처리되는지 체크
 *
 * 단계별 절차:
 * 1. 회원 생성
 * 2. 게시글 생성
 * 3. 정상 좋아요 등록
 * 4. 2중 중복 좋아요 방지(409)
 * 5. 유효하지 않은 post_id로 좋아요 에러 확인
 */
export async function test_api_discussionboard_postLikes_test_create_post_like_success(
  connection: api.IConnection,
) {
