import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_postLikes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_postLikes";

/**
 * 관리자 또는 모더레이터가 게시글 좋아요(Post Like) 메타데이터(예: timestamp, audit 태그)를 변경하는 기능의 E2E 검증
 *
 * 목적 및 비즈니스 맥락:
 *  - 일반 사용자(멤버)는 자신 또는 타인의 좋아요 기록을 편집할 수 없으나, 데이터 정합성/준수/이력 보전 등의 이슈로 인해 관리자 또는 모더레이터만 특정 필드(예: created_at)를 편집할 수 있음
 *  - ID(Like id) 기준으로 PUT 메소드 호출 시, 허용된 메타데이터만 변경되고 식별자(post_id/member_id)는 불변임이 콘트랙트로 지정됨
 *  - 잘못된 권한(예: 일반 회원)이 시도할 경우 401/403 권한 예외가 발생해야 한다
 *
 * 시나리오 요약:
 * 1. 회원 1명을 생성한다
 * 2. 게시글을 1개 생성한다
 * 3. 회원1과 게시글1을 기반으로 좋아요를 1개 생성한다
 * 4. (관리자/모더레이터 권한 시뮬레이션 또는 connection 가정)
 * 5. PUT /discussionboard/postLikes/{id} (like id)로 created_at 등 메타데이터 업데이트를 시도한다. 결과로 변경된 값, 불변값을 검증한다
 * 6. PUT body에 참조값(post_id/member_id) 변경을 시도해도 해당 필드는 실질적으로 불변임을 확인한다
 * 7. 일반 회원 권한에서는 putById 호출 시 권한 에러가 발생하는지 검증한다(TestValidator.error 사용)
 */
export async function test_api_discussionboard_test_update_post_like_metadata_by_admin(
  connection: api.IConnection,
) {
  // 1. 회원 생성
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. 게시글 생성
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. 좋아요 생성
  const like = await api.functional.discussionboard.postLikes.post(connection, {
    body: {
      post_id: post.id,
      member_id: member.id,
      ...typia.random<Omit<Idiscussionboard_postLikes.ICreate, "post_id" | "member_id">>()
    },
  });
  typia.assert(like);

  // 4. (관리자 권한 시뮬레이션 또는 connection 사용)

  // 5. 허용된 필드(created_at)만 업데이트
  const updatedCreatedAt = new Date(Date.now() + 5000).toISOString();
  const updated = await api.functional.discussionboard.postLikes.putById(connection, {
    id: like.id,
    body: { created_at: updatedCreatedAt },
  });
  typia.assert(updated);
  TestValidator.equals("created_at 변경됨")(updated.created_at)(updatedCreatedAt);
  TestValidator.equals("post_id 불변")(updated.post_id)(like.post_id);
  TestValidator.equals("member_id 불변")(updated.member_id)(like.member_id);

  // 6. 불변 필드(post_id, member_id)도 변경 시도 → 실제 값은 불변이어야 함
  const updateAttempt = await api.functional.discussionboard.postLikes.putById(connection, {
    id: like.id,
    body: {
      post_id: typia.random<string>(),
      member_id: typia.random<string>(),
      created_at: updatedCreatedAt,
    },
  });
  typia.assert(updateAttempt);
  TestValidator.equals("post_id 무시 또는 불변")(updateAttempt.post_id)(like.post_id);
  TestValidator.equals("member_id 무시 또는 불변")(updateAttempt.member_id)(like.member_id);

  // 7. 일반 회원 권한으로 putById 호출 시 권한 오류
  // (별도의 인증 api가 없다면 동일 connection, 실 서비스에서는 회원 인증 후 재시도 필요)
  TestValidator.error("일반 회원은 메타데이터 수정 불가")(
    async () => {
      await api.functional.discussionboard.postLikes.putById(connection, {
        id: like.id,
        body: { created_at: updatedCreatedAt },
      });
    },
  );
}

