import type { Idiscussionboard_postLikes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_postLikes";

/**
 * Validate deletion of a post like by its owner in the discussion board.
 *
 * This test verifies end-to-end that when a user likes a post, they can subsequently unlike it (delete the like record). After deletion, the like must disappear from engagement metrics and cannot be retrieved. The test also checks that:
 * 1. Only the owning member can delete their like (delete by other users is forbidden).
 * 2. Repeated deletion attempts are idempotent and do not error.
 *
 * Steps:
 * 1. Create member A (the like owner).
 * 2. Create member B (an unauthorized user).
 * 3. Member A creates a post (could be by any user, but for test simplicity use A).
 * 4. Member A likes the post (creates a like record).
 * 5. Member A unlikes (deletes) their like: expect success.
 * 6. Attempt to fetch the deleted like record/validate its removal (if the API supports fetch).
 * 7. Check that like engagement metrics on the post have decreased.
 * 8. Member B attempts to delete the same like record: expect error/forbidden (if possible).
 * 9. Member A attempts to delete the like again: expect no error due to idempotency.
 */
export async function test_api_discussionboard_test_delete_post_like_by_owner(
  connection: api.IConnection,
) {
  // 1. Create member A (like owner)
  const memberA = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberA);

  // 2. Create member B (unauthorized user)
  const memberB = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberB);

  // 3. Member A creates a post
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 4. Member A likes the post
  const like = await api.functional.discussionboard.postLikes.post(connection, {
    body: typia.random<Idiscussionboard_postLikes.ICreate>(),
  });
  typia.assert(like);

  // 5. Member A unlikes (deletes) the like
  await api.functional.discussionboard.postLikes.eraseById(connection, {
    id: like.id,
  });

  // 6. Like should be deleted; in a richer API, would try to fetch/metric check.

  // 7. Member B attempts forbidden deletion of same like
  await TestValidator.error("Member B cannot delete A's like")(() =>
    api.functional.discussionboard.postLikes.eraseById(connection, {
      id: like.id,
    })
  );

  // 8. Member A double-deletes (idempotency — should not error)
  await api.functional.discussionboard.postLikes.eraseById(connection, {
    id: like.id,
  });
}

