import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { INotificationPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/INotificationPreference";

/**
 * Validates full and conflicting updates of notification preferences with permission and constraint enforcement.
 *
 * Business context:
 * Notification preferences are per-member rules dictating how users receive alerts. Members can update their own preferences; admins may be able to update others, but ordinary members cannot.
 * Each (member, type, channel) must be unique. This test covers update success, uniqueness constraints, permission enforcement, and error behavior.
 *
 * Steps:
 * 1. Register Owner member (A)
 * 2. Register secondary member (B)
 * 3. Create two notification preferences for member A
 * 4. [SUCCESS] Update pref1 fully to a new unique (type, channel, enabled)
 * 5. [CONFLICT] Attempt update to duplicate (type, channel) as pref2—should fail
 * 6. [FORBIDDEN or PSEUDO] Simulate attempt to update pref1 as B—should fail (see note below if SDK lacks real auth switching)
 * 7. [NOT FOUND] Update with invalid/nonexistent ID—should fail
 * 8. [BAD REQUEST] Update with missing/invalid fields—should fail
 *
 * Note: If the SDK does not provide explicit user role/auth switching, the forbidden update test step is left illustrative.
 */
export async function test_api_discussionboard_test_update_notification_preference_with_permission_and_conflict_checks(
  connection: api.IConnection,
) {
  // 1. Register Owner member (A)
  const memberACreate = typia.random<IDiscussionboardMember.ICreate>();
  const memberA = await api.functional.discussionboard.members.post(connection, { body: memberACreate });
  typia.assert(memberA);

  // 2. Register secondary member (B)
  const memberBCreate = typia.random<IDiscussionboardMember.ICreate>();
  const memberB = await api.functional.discussionboard.members.post(connection, { body: memberBCreate });
  typia.assert(memberB);

  // 3. Create two notification preferences for member A
  const pref1Create = typia.random<INotificationPreference.ICreate>();
  pref1Create.memberId = memberA.id;
  const pref1 = await api.functional.discussionboard.notificationPreferences.post(connection, { body: pref1Create });
  typia.assert(pref1);

  const pref2Create = typia.random<INotificationPreference.ICreate>();
  pref2Create.memberId = memberA.id;
  // Make type/channel distinct from pref1:
  while (
    pref2Create.type === pref1.type &&
    pref2Create.channel === pref1.channel
  ) {
    pref2Create.type = typia.random<typeof pref2Create.type>();
    pref2Create.channel = typia.random<typeof pref2Create.channel>();
  }
  const pref2 = await api.functional.discussionboard.notificationPreferences.post(connection, { body: pref2Create });
  typia.assert(pref2);

  // 4. [SUCCESS] Update pref1 to a new unique (type, channel, enabled)
  const uniqueUpdate = typia.random<INotificationPreference.IUpdate>();
  // Ensure uniqueness (not colliding with pref2 type/channel):
  while (
    uniqueUpdate.type === pref2.type &&
    uniqueUpdate.channel === pref2.channel
  ) {
    uniqueUpdate.type = typia.random<typeof uniqueUpdate.type>();
    uniqueUpdate.channel = typia.random<typeof uniqueUpdate.channel>();
  }
