import type { IPageIDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardReport";

/**
 * 신고(report) 필터 및 페이지네이션 조회 E2E 테스트.
 *
 * - 복수의 멤버가 다양한 게시글/댓글을 대상으로 다양한 사유, 시간대 조합으로 신고(report)를 생성한다.
 * - 이후 리포트 목록 조회 API에 reporter, category, target_post_id, target_comment_id, createdAt 범위 등 다양한 필터와 페이지네이션(limit/offset) 조합을 보내 결과가 기대와 일치하는지 검증한다.
 * - 권한 없는 사용자, 잘못된 요청 구조(지원되지 않는 필터 포함 등) 에러 응답도 확인한다.
 * - 테스트 환경상 별도의 moderator/admin 인증 API가 없다면, 권한 강화/전환 step은 생략(메시지로 명시)
 */
export async function test_api_discussionboard_test_list_reports_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. 테스트 회원 3명 생성
  const members = await ArrayUtil.asyncRepeat(3)(async () => {
    const member = await api.functional.discussionboard.members.post(connection, {
      body: typia.random<IDiscussionboardMember.ICreate>(),
    });
    typia.assert(member);
    return member;
  });

  // 2. 게시글 2개 생성
  const posts = await ArrayUtil.asyncRepeat(2)(async (idx) => {
    const post = await api.functional.discussionboard.posts.post(connection, {
      body: typia.random<IDiscussionboardPost.ICreate>(),
    });
    typia.assert(post);
    return post;
  });

  // 3. 댓글 2개 생성(각기 다른 게시글에)
  const comments = await ArrayUtil.asyncRepeat(2)(async (idx) => {
    const comment = await api.functional.discussionboard.comments.post(connection, {
      body: typia.random<IDiscussionboardComment.ICreate>(),
    });
    typia.assert(comment);
    return comment;
  });

  // 4. reporter/post/comment/category/시간대 골고루 6개의 report 생성
  const categories = ["spam", "abuse", "other"];
  const timeBase = new Date();
  const reports = [];
  for (let i = 0; i < 6; ++i) {
    const reporter = members[i % members.length];
    const targetPost = posts[i % posts.length];
    const targetComment = comments[i % comments.length];
    const category = categories[i % categories.length];
    // 생성 시점 분포
    const createdAt = new Date(timeBase.getTime() - i * 60 * 60 * 1000); // 1시간 간격 시프트
    const report = await api.functional.discussionboard.reports.post(connection, {
      body: {
        ...typia.random<IDiscussionboardReport.ICreate>(),
        reporter_id: reporter.id,
        reason_category: category,
        target_post_id: i < 3 ? targetPost.id : undefined,
        target_comment_id: i >= 3 ? targetComment.id : undefined,
        created_at: createdAt.toISOString(),
      },
    });
    typia.assert(report);
    reports.push({ ...report, reporter, targetPost, targetComment, category, createdAt });
  }

  // 5. moderator/admin 인증 단계 생략(별도 API 없음 가정)
  // 6. 다양한 필터로 검색 및 result contents, pagination, total 검증
  // 1) reporter_id 필터
  const reporterId = members[0].id;
  const filterByReporter = await api.functional.discussionboard.reports.patch(connection, {
    body: { reporter_id: reporterId } as any,
  });
  typia.assert(filterByReporter);
  TestValidator.predicate("리포터 아이디 필터가 일치하는 지 여부")(
    filterByReporter.data.every((x: any) => x.reporter_id === reporterId),
  );

  // 2) 카테고리 필터
  const reasonCategory = categories[1];
  const filterByCategory = await api.functional.discussionboard.reports.patch(connection, {
    body: { reason_category: reasonCategory } as any,
  });
  typia.assert(filterByCategory);
  TestValidator.predicate("카테고리 필터가 일치하는 지 여부")(
    filterByCategory.data.every((x: any) => x.reason_category === reasonCategory),
  );

  // 3) target_post_id 필터
  const targetPostId = posts[0].id;
  const filterByPost = await api.functional.discussionboard.reports.patch(connection, {
    body: { target_post_id: targetPostId } as any,
  });
  typia.assert(filterByPost);
  TestValidator.predicate("포스트 타겟 필터 일치 여부")(
    filterByPost.data.every((x: any) => x.target_post_id === targetPostId),
  );

  // 4) 날짜 범위 필터
  const begin = new Date(timeBase.getTime() - 3 * 60 * 60 * 1000).toISOString();
  const end = timeBase.toISOString();
  const filterByDate = await api.functional.discussionboard.reports.patch(connection, {
    body: { created_from: begin, created_to: end } as any,
  });
  typia.assert(filterByDate);
  TestValidator.predicate("날짜 범위 필터 일치 여부")(
    filterByDate.data.every((x: any) =>
      new Date(x.created_at) >= new Date(begin) &&
      new Date(x.created_at) <= new Date(end),
    ),
  );

  // 5) limit/offset 페이지네이션(페이지 2개 분할)
  const pageLimit = 3;
  const page1 = await api.functional.discussionboard.reports.patch(connection, {
    body: { limit: pageLimit, offset: 0 } as any,
  });
  const page2 = await api.functional.discussionboard.reports.patch(connection, {
    body: { limit: pageLimit, offset: pageLimit } as any,
  });
  typia.assert(page1);
  typia.assert(page2);
  TestValidator.equals("페이지1 limit")(
    page1.data.length,
  )(Math.min(page1.total, pageLimit));
  TestValidator.equals("페이지2 limit")(
    page2.data.length,
  )(Math.max(0, page2.total - pageLimit));
  TestValidator.predicate("페이지 합계와 total일치")(
    page1.data.length + page2.data.length <= page1.total,
  );

  // 7. 권한 없는(로그인X) 계정 접근(별도 인증 API없으므로 생략)
  // 8. 잘못된 요청 (존재하지않는 필드 포함) 400 에러 발생 확인
  await TestValidator.error("잘못된 필드, 400 에러 발생")(
    async () =>
      await api.functional.discussionboard.reports.patch(connection, {
        body: { not_a_field: "wrong" } as any,
      }),
  );
}

