import type { IDiscussionboardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardReport";

/**
 * Validate system enforcement of anti-duplicate reporting policy within a time window.
 *
 * This test ensures that a single member cannot file multiple reports against the same target entity (post or comment) in rapid succession where such action is restricted by platform policy. It also validates that other members are not blocked from reporting the same content and that duplicate prevention is scope-limited (does not block different targets).
 *
 * Steps:
 * 1. Create a member (MemberA) who will perform initial and duplicate reports.
 * 2. Create another member (MemberB) to test unrestricted reporting.
 * 3. Create a post (PostX) which will be the reporting target.
 * 4. MemberA files a report on PostX successfully.
 * 5. MemberA attempts to report PostX again within the restricted window – expect a 409 Conflict or validation error.
 * 6. MemberB files a report on PostX successfully without restriction.
 * 7. MemberA files a report on a different, unrelated post (PostY) – should succeed, confirming the restriction is only for same target.
 */
export async function test_api_discussionboard_test_prevent_duplicate_report_within_window(
  connection: api.IConnection,
) {
  // 1. Create MemberA
  const memberA = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberA);

  // 2. Create MemberB
  const memberB = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberB);

  // 3. Create PostX
  const postX = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(postX);

  // 4. MemberA files a report on PostX (should succeed)
  const reportBodyA1 = {
    ...typia.random<IDiscussionboardReport.ICreate>(),
    reporterId: memberA.id,
    targetPostId: postX.id,
  };
  const reportA1 = await api.functional.discussionboard.reports.post(connection, {
    body: reportBodyA1,
  });
  typia.assert(reportA1);
  TestValidator.equals("report links to correct member")(
    reportA1.reporterId
  )(memberA.id);
  TestValidator.equals("report links to correct post")(
    reportA1.targetPostId
  )(postX.id);

  // 5. MemberA attempts to report PostX again (should fail with duplicate error)
  await TestValidator.error("Duplicate report by MemberA on same PostX within window should fail")(
    async () => {
      await api.functional.discussionboard.reports.post(connection, {
        body: {
          ...typia.random<IDiscussionboardReport.ICreate>(),
          reporterId: memberA.id,
          targetPostId: postX.id,
        },
      });
    },
  );

  // 6. MemberB files a report on PostX (should be allowed)
  const reportBodyB = {
    ...typia.random<IDiscussionboardReport.ICreate>(),
    reporterId: memberB.id,
    targetPostId: postX.id,
  };
  const reportB = await api.functional.discussionboard.reports.post(connection, {
    body: reportBodyB,
  });
  typia.assert(reportB);
  TestValidator.equals("report by B links to correct member")(
    reportB.reporterId
  )(memberB.id);
  TestValidator.equals("report by B links to correct post")(
    reportB.targetPostId
  )(postX.id);

  // 7. MemberA files a report on a different post (PostY)
  const postY = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(postY);
  const reportBodyA2 = {
    ...typia.random<IDiscussionboardReport.ICreate>(),
    reporterId: memberA.id,
    targetPostId: postY.id,
  };
  const reportA2 = await api.functional.discussionboard.reports.post(connection, {
    body: reportBodyA2,
  });
  typia.assert(reportA2);
  TestValidator.equals("report by A links to correct member for new post")(
    reportA2.reporterId
  )(memberA.id);
  TestValidator.equals("report by A links to correct (other) post")(
    reportA2.targetPostId
  )(postY.id);
}

