/**
 * Validate creation of an appeal by a member regarding a moderation action that affects them.
 *
 * This test covers the following cases:
 * 1. Successful creation of an appeal by a member for a moderation action (ban, warning, or content moderation) that directly targets them.
 *    - Ensure the appeal is created with expected status and required fields populated.
 *    - Confirm audit log behavior (structurally, by checking appeal presence and status, as audit log is assumed platform-handled).
 * 2. Attempt to appeal a moderation action as a non-affected member (should be rejected).
 * 3. Attempt to create an appeal with missing required fields (e.g., missing moderation_action_id, missing message) or invalid data (e.g., empty message, obviously bad type enum/value). All should be rejected.
 *
 * Steps:
 * 1. Create a member (appellant).
 * 2. Create a moderation action targeting this member (required for correct referencing).
 * 3. Successfully appeal the moderation action as the member, verify output fields and correctness.
 * 4. Create another member (non-affected), attempt to appeal (should be rejected).
 * 5. Attempt to submit appeal with missing/invalid fields (should be rejected).
 */
export async function test_api_discussionboard_test_create_appeal_as_member_with_valid_action(
  connection: api.IConnection,
) {
  // 1. Create a member (appellant)
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create a moderation action targeting this member
  const moderationAction = await api.functional.discussionboard.moderationActions.post(connection, {
    body: typia.random<IDiscussionboardModerationAction.ICreate>(),
  });
  typia.assert(moderationAction);

  // 3. Successfully submit an appeal as the affected member
  const appealInput = typia.random<discussionboard_appeals.ICreate>();
  // Overwrite so the correct references are set: member and moderation_action
  appealInput.appellant_member_id = member.id;
  appealInput.moderation_action_id = moderationAction.id;
  const appeal = await api.functional.discussionboard.appeals.post(connection, {
    body: appealInput,
  });
