  // 4. Create another member (non-affected)
  const anotherMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(anotherMember);

  // 5. Attempt invalid appeal: as non-affected member
  const invalidAppealInput = { ...appealInput, appellant_member_id: anotherMember.id };
  await TestValidator.error("Non-affected member should not be able to appeal")(async () => {
    await api.functional.discussionboard.appeals.post(connection, {
      body: invalidAppealInput,
    });
  });

  // 6. Attempt missing required fields
  const missingModerationId = { ...appealInput };
  delete missingModerationId.moderation_action_id;
  await TestValidator.error("Missing moderation_action_id should fail")(async () => {
    await api.functional.discussionboard.appeals.post(connection, {
      body: missingModerationId,
    });
  });

  const missingMessage = { ...appealInput };
  delete missingMessage.message;
  await TestValidator.error("Missing message field should fail")(async () => {
    await api.functional.discussionboard.appeals.post(connection, {
      body: missingMessage,
    });
  });
}

