import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMemberProfile";
import type { IPageIDiscussionboardMemberProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardMemberProfile";

/**
 * Validates paginated, filtered retrieval of member profiles.
 *
 * Simulates an admin or privileged actor managing the member directory. The test creates several discussionboard members and attaches custom profiles to them, using a variety of display names, bios, locales and timezone values. Then, the test retrieves a paginated list of profiles, using filters (partial display name, specific locale/timezone, created window) and validates that returned data matches expectations. Also verifies correct paging and filter behavior, including miss cases.
 *
 * Steps:
 * 1. Create 5 member accounts with unique emails/names.
 * 2. Attach a distinct profile to each member (varying displayName, bio, locale, timezone).
 * 3. Pick multiple filter criteria based on the seeded profile data (e.g., match display substring, or certain locale/timezone seen in profiles).
 * 4. Issue paginated profile search requests with each filter.
 * 5. Assert for each filter: returned items ALL match the condition, no extraneous/out-of-range records, and pagination is correct.
 * 6. Issue a filter that yields no matches and assert empty result.
 */
export async function test_api_discussionboard_test_list_member_profiles_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create members and their profiles with controlled variance
  const profiles: any[] = [];
  const uniqueNames = [
    "E2E_AliceWolfe",
    "E2E_BobYoon",
    "E2E_CarolMin",
    "E2E_DavePark",
    "E2E_EveShin",
  ];
  const locales = [
    "en-US",
    "ko-KR",
    "ja-JP",
    "zh-CN",
    "fr-FR",
  ];
  const timezones = [
    "Asia/Seoul",
    "America/New_York",
    "Europe/Paris",
    "Asia/Tokyo",
    "Asia/Shanghai",
  ];
  const bios = [
    "Cafe owner and writer.",
    "Quantum enthusiast.",
    "Karate star & political junkie.",
    "Crypto investor.",
    "Literature student.",
  ];
  for (let i = 0; i < 5; ++i) {
    // 1.1. Register member
    const member = await api.functional.discussionboard.members.post(connection, {
      body: { email: `e2e_test_user_${i + 1}@example.com`, nickname: uniqueNames[i], password: "TestPassword123!" },
    });
    typia.assert(member);
    // 1.2. Create profile
    const profile = await api.functional.discussionboard.memberProfiles.post(connection, {
      body: {
        // FK is assumed available on member (for .id or .memberId usage, adjust as real runtime requires)
        memberId: member.id ?? member.memberId ?? member._id ?? i + 10000, // fallback if field is ambiguous
        displayName: uniqueNames[i],
        bio: bios[i],
        locale: locales[i],
        timezone: timezones[i],
      },
    });
    typia.assert(profile);
    profiles.push(profile);
  }
  // 2. Test: partial displayName filter (substring match "E2E_" should match all)
  {
    const result = await api.functional.discussionboard.memberProfiles.patch(connection, {
      body: { displayName: "E2E_", page: 1, size: 10 },
    });
    typia.assert(result);
    // All returned should have matching substring
    for (const entry of result.data ?? result.items ?? [])
      if (!(entry.displayName ?? "").includes("E2E_"))
        throw new Error(`Expected displayName to include 'E2E_' but got '${entry.displayName ?? ""}'`);
  }
  // 3. Test: locale filter (e.g., "ko-KR")
  {
    const result = await api.functional.discussionboard.memberProfiles.patch(connection, {
      body: { locale: "ko-KR", page: 1, size: 5 },
    });
    typia.assert(result);
    for (const entry of result.data ?? result.items ?? [])
      if (entry.locale !== "ko-KR")
        throw new Error(`Expected locale 'ko-KR' but got '${entry.locale}'`);
  }
  // 4. Test: timezone filter (e.g., "Asia/Seoul")
  {
    const result = await api.functional.discussionboard.memberProfiles.patch(connection, {
      body: { timezone: "Asia/Seoul", page: 1, size: 5 },
    });
    typia.assert(result);
    for (const entry of result.data ?? result.items ?? [])
      if (entry.timezone !== "Asia/Seoul")
        throw new Error(`Expected timezone 'Asia/Seoul' but got '${entry.timezone}'`);
  }
  // 5. Test: pagination works (page=2, size=2)
  {
    const result = await api.functional.discussionboard.memberProfiles.patch(connection, {
      body: { page: 2, size: 2 },
    });
    typia.assert(result);
    // Result must have at most 2 records
    const actual = (result.data ?? result.items ?? []);
    if (actual.length > 2)
      throw new Error(`Expected <=2 results for page 2/size 2, got ${actual.length}`);
  }
  // 6. Negative case: filter that should produce no matches
  {
    const result = await api.functional.discussionboard.memberProfiles.patch(connection, {
      body: { displayName: "NonExistentName", page: 1, size: 10 },
    });
    typia.assert(result);
    const actual = (result.data ?? result.items ?? []);
    if (actual.length !== 0)
      throw new Error(`Expected empty result set but got ${actual.length} records`);
  }
}

