/**
 * Validate that invalid profile updates are rejected and do not apply changes.
 *
 * This test ensures that when a member profile update is attempted with missing or
 * invalid required fields (e.g., empty display name, invalid locale), the API responds with
 * a validation error and does not alter the profile data.
 *
 * Steps:
 * 1. Register a test member for scenario preparation.
 * 2. Create an initial, valid member profile for the member.
 * 3. Attempt several invalid updates to the profile (such as empty display name, invalid locale code, etc).
 * 4. Verify that each invalid update returns an error (validation is enforced).
 * 5. Confirm, as far as possible given DTO opacity, that the profile remains unchanged after failed updates.
 */
export async function test_api_discussionboard_test_update_member_profile_with_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register a member
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create a valid member profile
  const profile = await api.functional.discussionboard.memberProfiles.post(connection, {
    body: typia.random<IDiscussionboardMemberProfile.ICreate>(),
  });
  typia.assert(profile);

  // 3. Prepare invalid update scenarios: empty display name, invalid locale code, both
  const invalidUpdates = [
    { displayName: "" },
    { locale: "invalid-locale" },
    { displayName: "", locale: "invalid-locale" },
  ];

  for (const invalidBody of invalidUpdates) {
    await TestValidator.error("profile update validation failure")(
      async () => {
        await api.functional.discussionboard.memberProfiles.putById(connection, {
          id: profile.id,
          body: invalidBody as IDiscussionboardMemberProfile.IUpdate,
        });
      },
    );
