/**
 * Validate soft deletion of a member's own profile (self-delete scenario).
 *
 * This test verifies that when a member deletes their own profile using the soft-delete endpoint:
 * 1. The profile is not physically deleted from the database but marked as deleted (soft delete marker set).
 * 2. The action can only be performed by the profile owner (self-delete pattern).
 * 3. Deletion marker is present after deletion, and in absence of specific DTO types, common marker fields are checked at runtime.
 *
 * Steps:
 * 1. Register a member (simulates user registration).
 * 2. Create a member profile (if not created at registration, to ensure a profile exists).
 * 3. Delete the profile using the soft-delete API (as owner).
 * 4. Assert that the returned profile contains a deletion marker (`deleted`, `is_deleted`, or `deleted_at`).
 * 5. Assert the deletion marker is set (truthy or present).
 * 6. (Commented) Further checks/audit logs can be added if API support is available.
 */
export async function test_api_discussionboard_test_soft_delete_own_member_profile(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create a profile for that member
  const profile: IDiscussionboardMemberProfile = await api.functional.discussionboard.memberProfiles.post(connection, {
    body: typia.random<IDiscussionboardMemberProfile.ICreate>(),
  });
  typia.assert(profile);

  // 3. Delete the profile (soft delete)
  const deletedProfile: IDiscussionboardMemberProfile = await api.functional.discussionboard.memberProfiles.eraseById(connection, {
    id: profile.id,
  });
  typia.assert(deletedProfile);

  // 4. Assert presence of a soft-delete marker after deletion
  if (!("deleted" in deletedProfile || "is_deleted" in deletedProfile || "deleted_at" in deletedProfile)) {
    throw new Error("Soft deletion marker (deleted, is_deleted, deleted_at) not found on profile");
  }
  // 5. Assert correct soft-delete property semantics (truthy or present)
  if ("deleted" in deletedProfile) {
    TestValidator.predicate("profile.deleted should be truthy")(!!deletedProfile.deleted);
  }
  if ("is_deleted" in deletedProfile) {
    TestValidator.predicate("profile.is_deleted should be truthy")(!!deletedProfile.is_deleted);
  }
  if ("deleted_at" in deletedProfile) {
    TestValidator.predicate("profile.deleted_at should be present")(!!deletedProfile.deleted_at);
  }
  // (Optional) If fetch or audit API existed, we would check post-delete state/audit here.
}

