import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardComment";
import type { IDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentReport";
import type { IPageIDiscussionboardCommentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCommentReport";

/**
 * Validates filtered and paginated retrieval of comment reports by a moderator.
 *
 * This test covers the end-to-end flow for a moderator retrieving comment reports using multiple filters (by comment, by member, by reason code) and pagination settings.
 *
 * Steps:
 * 1. Register a member who authors comments and files reports.
 * 2. Register a moderator (search-permitted user).
 * 3. The member creates a comment.
 * 4. The member files multiple reports on the comment (for filter and pagination diversity).
 * 5. Use the moderator account context (assume direct use as there is no API for login/switch).
 * 6. Perform several filtered/paginated queries on /commentReports:
 *    - By comment ID
 *    - By reporting member ID
 *    - By reason code (if present)
 *    - Paginate with size=2, fetch page 1 and 2
 *    - Edge: filter with random comment ID (empty result)
 * 7. Assertions:
 *    - Each result only includes expected records based on filter
 *    - Pagination and metadata fields are correct
 *    - Report record mandatory fields are present in result
 *    - When filter yields no results, the list is empty
 *
 * RBAC and privacy cannot be fully verified due to lack of role APIs.
 */
export async function test_api_discussionboard_test_list_comment_reports_with_various_filters_pagination_success_for_moderator(
  connection: api.IConnection,
) {
  // 1. Register a member who authors comments and files reports
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Register a moderator (for privileged listing - no explicit role function, but separate user)
  const moderator = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(moderator);

  // 3. Member creates a comment
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment);

  // 4. Member files multiple reports on the comment
  const reports = await ArrayUtil.asyncRepeat(3)(async () => {
    const report = await api.functional.discussionboard.commentReports.post(connection, {
      body: typia.random<IDiscussionboardCommentReport.ICreate>(),
    });
    typia.assert(report);
    return report;
  });

  // Use fields from filed reports for precise filters
  const oneReport = reports[0];

  // 5. Moderator context (no explicit login/switch API, assumed permissible via separate user)

  // 6a. Filter by comment ID
  const filterByComment = await api.functional.discussionboard.commentReports.patch(connection, {
    body: { comment_id: comment.id, page: 1, size: 10 } as IDiscussionboardCommentReport.IRequest,
  });
  typia.assert(filterByComment);
  filterByComment.data.forEach((r: any) => {
    TestValidator.equals("comment_id matches")(r.comment_id)(comment.id);
  });

  // 6b. Filter by reporting member
  const filterByMember = await api.functional.discussionboard.commentReports.patch(connection, {
    body: { reporting_member_id: member.id, page: 1, size: 10 } as IDiscussionboardCommentReport.IRequest,
  });
  typia.assert(filterByMember);
  filterByMember.data.forEach((r: any) => {
    TestValidator.equals("reporting_member_id matches")(r.reporting_member_id)(member.id);
  });

  // 6c. Filter by reason code (if available)
  if (oneReport.reason_code !== undefined) {
    const filterByReason = await api.functional.discussionboard.commentReports.patch(connection, {
      body: { reason_code: oneReport.reason_code, page: 1, size: 10 } as IDiscussionboardCommentReport.IRequest,
    });
    typia.assert(filterByReason);
    filterByReason.data.forEach((r: any) => {
      TestValidator.equals("reason_code matches")(r.reason_code)(oneReport.reason_code);
    });
  }

  // 6d. Pagination: page 1 and 2 with size=2
  const paginatedPage1 = await api.functional.discussionboard.commentReports.patch(connection, {
    body: { page: 1, size: 2 } as IDiscussionboardCommentReport.IRequest,
  });
  typia.assert(paginatedPage1);
  TestValidator.equals("page size")(paginatedPage1.data.length)(2);
  TestValidator.equals("current page")(paginatedPage1.page)(1);

  const paginatedPage2 = await api.functional.discussionboard.commentReports.patch(connection, {
    body: { page: 2, size: 2 } as IDiscussionboardCommentReport.IRequest,
  });
  typia.assert(paginatedPage2);
  TestValidator.equals("current page")(paginatedPage2.page)(2);

  // 6e. Edge: filter with random comment_id that should yield zero results
  const emptyResult = await api.functional.discussionboard.commentReports.patch(connection, {
    body: { comment_id: typia.random<string>(), page: 1, size: 10 } as IDiscussionboardCommentReport.IRequest,
  });
  typia.assert(emptyResult);
  TestValidator.equals("no results")(emptyResult.data.length)(0);

  // 7. Validate required report fields and page metadata
  paginatedPage1.data.forEach((report: any) => {
    TestValidator.predicate("report has id")(!!report.id);
    TestValidator.predicate("report has comment_id")(!!report.comment_id);
    TestValidator.predicate("report has reporting_member_id")(!!report.reporting_member_id);
  });
  TestValidator.predicate("metadata: page is 1")(paginatedPage1.page === 1);
  TestValidator.predicate("metadata: size is 2")(paginatedPage1.size === 2);

  // 8. RBAC/privacy cannot be checked as there is no role or auth switching function in the API
}

