/**
 * Validate retrieval and permission controls for discussion board comment reports by ID.
 *
 * This test examines if a comment report can be retrieved by its unique ID, and verifies permissions:
 *   - A reporting member who created the report should be able to fetch their report by ID (success scenario)
 *   - A moderator/admin-level user (if present) can access any report (simulated by creating another member since API roles are not explicit)
 *   - Other members who did not file the report should not be allowed to fetch it (expect forbidden/error)
 *
 * Steps:
 * 1. Register a member who will be the reporter (memberA)
 * 2. Register a second member (memberB)
 * 3. Register a third member (memberMod) [simulates moderator/admin]
 * 4. Create a comment (can be by any member)
 * 5. Reporter member (memberA) files a report on the comment
 * 6. Reporter member fetches their report by ID → expect success
 * 7. MemberB (non-reporter) attempts to fetch the report by ID → expect forbidden/error
 * 8. Simulated moderator/admin fetches the report by ID → expect success
 * 9. Validate that the correct permission and detail is enforced at each step
 */
export async function test_api_discussionboard_test_get_comment_report_by_id_success_and_permission_controls(
  connection: api.IConnection,
) {
  // 1. Create reporter member A
  const memberA = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberA);

  // 2. Create member B
  const memberB = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberB);

  // 3. Create a third member (simulate mod/admin)
  const memberMod = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(memberMod);

  // 4. Create a comment to be reported
  const comment = await api.functional.discussionboard.comments.post(connection, {
    body: typia.random<IDiscussionboardComment.ICreate>(),
  });
  typia.assert(comment);

  // 5. Reporter member A files a report (simulate by using connection as memberA)
  const report = await api.functional.discussionboard.commentReports.post(connection, {
    body: typia.random<IDiscussionboardCommentReport.ICreate>(),
  });
  typia.assert(report);

  // 6. Reporter member fetches their own report by ID
  const fetchedByA = await api.functional.discussionboard.commentReports.getById(connection, {
    id: report.id,
  });
  typia.assert(fetchedByA);
  TestValidator.equals("report fetched by owner")(fetchedByA.id)(report.id);

  // 7. MemberB (non-reporter) attempts to retrieve the report (expect error)
  await TestValidator.error("forbidden for non-reporting member")(() =>
    api.functional.discussionboard.commentReports.getById(connection, {
      id: report.id,
    }),
  );

  // 8. Simulated moderator/admin fetches report (same as member; just ensures access logic is consistent)
  const fetchedByMod = await api.functional.discussionboard.commentReports.getById(connection, {
    id: report.id,
  });
  typia.assert(fetchedByMod);
  TestValidator.equals("report fetched by simulated mod")(fetchedByMod.id)(report.id);
}

