/**
 * Validate fetching discussionboard post details by ID, under all relevant role conditions (as technically feasible).
 *
 * Business context:
 * - Posts may have different visibility depending on status (published, hidden, deleted)
 * - Roles include author, admin (moderator), and general member. Visibility must be enforced properly.
 *
 * NOTE:
 * - No SDK support for authenticating/logging in as author, admin, or member (no login endpoints provided)
 * - No DTO field control for publication/visibility/soft-delete (all DTOs are 'any')
 * - So, author/admin/member flows will use the same connection context
 * - Cannot force masking/authorization failures as per scenario (all requests are unrestricted)
 *
 * 1. Register three members: author, admin (moderator), and regular member
 * 2. Author creates two posts (published and hidden, though in code both are equivalent)
 * 3. Fetch post by ID for published post — as author, as admin, as other member (technically identical API result here)
 * 4. Fetch by ID for 'hidden' post — as author, as admin, as member (again, identical results)
 * 5. Attempt to fetch a nonexistent post (expect error)
 * 6. For each fetch, assert with typia and sanity-check presence of ID field
 */
export async function test_api_discussionboard_test_get_post_by_id_success_and_permission_cases(connection: api.IConnection) {
  // 1. Register members
  const author = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(author);

  const admin = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(admin);

  const member = await api.functional.discussionboard.members.post(connection, { body: typia.random<IDiscussionboardMember.ICreate>() });
  typia.assert(member);

  // 2. Create two posts
  const publishedPost = await api.functional.discussionboard.posts.post(connection, { body: typia.random<IDiscussionboardPost.ICreate>() });
  typia.assert(publishedPost);

  const hiddenPost = await api.functional.discussionboard.posts.post(connection, { body: typia.random<IDiscussionboardPost.ICreate>() });
  typia.assert(hiddenPost);

  // 3. Fetch published post as different roles (uses same connection)
  const fetchedByAuthor = await api.functional.discussionboard.posts.getById(connection, { id: publishedPost.id });
  typia.assert(fetchedByAuthor);
  TestValidator.equals('published post id')(fetchedByAuthor.id)(publishedPost.id);

  const fetchedByAdmin = await api.functional.discussionboard.posts.getById(connection, { id: publishedPost.id });
  typia.assert(fetchedByAdmin);
  TestValidator.equals('published post id')(fetchedByAdmin.id)(publishedPost.id);

  const fetchedByMember = await api.functional.discussionboard.posts.getById(connection, { id: publishedPost.id });
  typia.assert(fetchedByMember);
  TestValidator.equals('published post id')(fetchedByMember.id)(publishedPost.id);

  // 4. Fetch hidden post (identical code path)
  const hiddenByAuthor = await api.functional.discussionboard.posts.getById(connection, { id: hiddenPost.id });
  typia.assert(hiddenByAuthor);
  TestValidator.equals('hidden post id')(hiddenByAuthor.id)(hiddenPost.id);

  const hiddenByAdmin = await api.functional.discussionboard.posts.getById(connection, { id: hiddenPost.id });
  typia.assert(hiddenByAdmin);
  TestValidator.equals('hidden post id')(hiddenByAdmin.id)(hiddenPost.id);

  const hiddenByMember = await api.functional.discussionboard.posts.getById(connection, { id: hiddenPost.id });
  typia.assert(hiddenByMember);
  TestValidator.equals('hidden post id')(hiddenByMember.id)(hiddenPost.id);

  // 5. Non-existent post id (should 404)
  TestValidator.error('404 for not found')(async () => {
    await api.functional.discussionboard.posts.getById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThread";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * 다양한 케이스로 토론 게시판의 게시글 생성(POST /discussionboard/posts)을 E2E로 검증한다.
 *
 * 1. 인증된 멤버가 정상적인 스레드에, 모든 필수 값이 들어간 게시글을 정상 생성하면 성공해야 한다.
 * 2. thread/author/title/body 등 필수 키 누락 혹은 invalid value로 post 요청시 validation에 실패해야 한다.
 * 3. 인증되지 않은(비로그인) 상태로 post 요청시 실패해야 한다.
 * 4. 존재하지 않거나(무작위 UUID 등), 잠긴(locked) thread에 post 요청시 실패해야 한다.
 * 5. title/body가 너무 짧거나 너무 길 때 anti-spam/length 정책에 따라 에러가 발생하는지 확인한다.
 *
 * 모든 케이스에서 반환결과로 id/timestamp/metadata등이 포함되는지 typia.assert()로 유효성 체크를 한다.
 */
export async function test_api_discussionboard_test_create_post_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // -- 1. 인증된 멤버, 정상적인 thread를 가지고 post 생성 성공 --
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  const thread = await api.functional.discussionboard.threads.post(connection, {
    body: typia.random<IDiscussionboardThread.ICreate>(),
  });
  typia.assert(thread);

  const postBody = typia.random<IDiscussionboardPost.ICreate>();
  // 필수키(스레드, 작성자, 타이틀, 본문) 값 thread, member 기반 대입
  if (postBody.threadId !== undefined) postBody.threadId = thread.id;
  if (postBody.authorId !== undefined) postBody.authorId = member.id;
  if (postBody.title === undefined || postBody.title === null) postBody.title = "글 제목입니다";
  if (postBody.body === undefined || postBody.body === null) postBody.body = "이것은 본문의 내용입니다.";
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: postBody,
  });
  typia.assert(post);
  // id/timestamp/meta 등이 포함되었는지 확인
  TestValidator.predicate("post는 id, 타임스탬프(메타), 기본 포함")(!!post.id && !!post.createdAt);

  // -- 2. 필수 property 누락 시 validation error (예, title 제외)--
  const missingTitleBody = { ...postBody };
  delete missingTitleBody.title;
  await TestValidator.error("title 누락 validation 에러")(() =>
    api.functional.discussionboard.posts.post(connection, { body: missingTitleBody })
  );

  // -- 3. 인증 없음 (connection.header.Authorization 제거 효과)--
  const guestConnection = { ...connection, headers: { ...connection.headers } } as api.IConnection;
  if (!guestConnection.headers) guestConnection.headers = {};
  delete guestConnection.headers.Authorization;
  await TestValidator.error("비로그인 게스트 불가")(() =>
    api.functional.discussionboard.posts.post(guestConnection, { body: postBody })
  );

  // -- 4. (a) 존재하지 않는 threadId, (b) 잠긴 thread 사용 --
  // (a) 임의의 UUID를 thread ID로
  const nonExistThreadBody = { ...postBody, threadId: typia.random<string>() };
  await TestValidator.error("존재하지 않는 threadId")(() =>
    api.functional.discussionboard.posts.post(connection, { body: nonExistThreadBody })
  );
  // (b) thread.locked이나 status값 조정(지원하면) 후 post 시도
  let lockedThread;
  try {
    lockedThread = await api.functional.discussionboard.threads.post(connection, {
      body: { ...(typia.random<IDiscussionboardThread.ICreate>()), locked: true },
    });
    typia.assert(lockedThread);
    const lockedThreadPostBody = { ...postBody, threadId: lockedThread.id };
    await TestValidator.error("locked thread에 post 시도실패")(() =>
      api.functional.discussionboard.posts.post(connection, { body: lockedThreadPostBody })
    );
  } catch (e) {
    // thread.locked property가 없거나 지원하지 않을 경우 스킵
  }

  // -- 5. anti-spam, 길이 에러: title/body 너무 짧거나 긴 경우--
  const shortTitleBody = { ...postBody, title: "a" };
  await TestValidator.error("title 너무 짧음")(() =>
    api.functional.discussionboard.posts.post(connection, { body: shortTitleBody })
  );

  const longBody = { ...postBody, body: "x".repeat(5001) };
  await TestValidator.error("body 너무 긺")(() =>
    api.functional.discussionboard.posts.post(connection, { body: longBody })
  );
}

