 *
 * This function tests that the /discussionboard/warnings POST endpoint correctly enforces:
 *  - Duplicate prevention (same member+action+type cannot be created twice)
 *  - Invalid references (fails with non-existent member or moderationAction IDs)
 *  - Permission checks (unauthorized user is forbidden from creating warnings)
 *
 * ## Steps
 * 1. Register a new member (via /discussionboard/members)
 * 2. Create a moderation action entry (via /discussionboard/moderationActions)
 * 3. Successfully create a warning for the member-action-type triplet
 * 4. Attempt to create a duplicate warning (same member/action/type) – must fail
 * 5. Attempt to create a warning with invalid (random) member ID – must fail
 * 6. Attempt to create a warning with invalid (random) moderationAction ID – must fail
 * 7. Attempt to create a warning using an unauthorized connection – must fail
 */
export async function test_api_discussionboard_test_create_warning_with_duplicate_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const member = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(member);

  // 2. Create a moderation action
  const moderationAction = await api.functional.discussionboard.moderationActions.post(connection, {
    body: typia.random<IDiscussionboardModerationAction.ICreate>(),
  });
