  // 3. Create a valid warning linking the member & moderationAction
  const baseWarningBody: IDiscussionboardWarning.ICreate = {
    ...(typia.random<IDiscussionboardWarning.ICreate>()),
    memberRef: member.id, // assume id property exists on member
    actionRef: moderationAction.id, // assume id property exists on moderationAction
  };
  const warning = await api.functional.discussionboard.warnings.post(connection, {
    body: baseWarningBody,
  });
  typia.assert(warning);

  // 4. Duplicate warning (same member-action-type) should fail
  await TestValidator.error("duplicate warning must fail")(
    async () => {
      await api.functional.discussionboard.warnings.post(connection, {
        body: baseWarningBody,
      });
    },
  );

