/**
 * 다양한 회원 권한별로 게시글 첨부파일 상세 조회 API의 접근 권한 및 예외 반환을 검증하는 테스트.
 *
 * - 본인 회원이 본인 첨부파일을 정상적으로 조회할 수 있는지
 * - 타 일반회원이 타인의 첨부파일 접근 시 적절히 거부되는지
 * - 관리자 또는 모더레이터 권한의 계정이 모든 첨부파일을 조회할 수 있는지
 * - 잘못된(uuid 형식 랜덤) 또는 존재하지 않는 첨부파일 ID로 조회 시 적절히 에러를 반환하는지
 *
 * 테스트 절차:
 * 1. userA(일반회원)로 회원가입/인증 및 게시글/첨부파일 업로드
 * 2. userA가 본인 첨부파일을 상세조회 (정상 성공)
 * 3. userB(다른 회원)로 가입/인증 후 userA 첨부파일 접근 시도 (권한 거부 또는 오류)
 * 4. admin(관리자권한) 회원 가입/인증 후 userA 첨부파일 접근 (성공)
 * 5. 무작위·유효하지 않은(존재하지 않는) UUID로 조회 시 오류 발생 검증
 *
 * 삭제(soft/hard delete) 상태 첨부파일 조회는 DELETE API 부재 등으로 테스트 불가시에 omit 처리
 */
export async function test_api_discussionboard_test_retrieve_post_attachment_by_id_with_permission_variants(
  connection: api.IConnection,
) {
  // 1. userA(일반 회원)로 회원가입
  const userA = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(userA);

  // 2. userA로 게시글(post) 작성
  const post = await api.functional.discussionboard.posts.post(connection, {
    body: typia.random<IDiscussionboardPost.ICreate>(),
  });
  typia.assert(post);

  // 3. userA로 post에 첨부파일(upload/metadata) 등록
  const attachment = await api.functional.discussionboard.postAttachments.post(connection, {
    body: typia.random<IDiscussionboardPostAttachment.ICreate>(),
  });
  typia.assert(attachment);

  // 4. userA가 본인 첨부파일을 정상적으로 상세조회
  const fetchedBySelf = await api.functional.discussionboard.postAttachments.getById(connection, {
    id: attachment.id,
  });
  typia.assert(fetchedBySelf);
  TestValidator.equals("본인 첨부파일 상세 조회 성공")(fetchedBySelf.id)(attachment.id);

  // 5. userB(일반 회원) 가입
  const userB = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(userB);

  // userB로 userA 첨부파일 접근 (권한 거부/오류 예상)
  await TestValidator.error("타인 첨부파일 일반 회원 접근 차단")(() =>
    api.functional.discussionboard.postAttachments.getById(connection, {
      id: attachment.id,
    })
  );

  // 6. 관리자 회원(admin) 가입
  const admin = await api.functional.discussionboard.members.post(connection, {
    body: typia.random<IDiscussionboardMember.ICreate>(),
  });
  typia.assert(admin);

  // 관리자 계정으로 userA 첨부파일 접근 (정상 성공)
  const fetchedByAdmin = await api.functional.discussionboard.postAttachments.getById(connection, {
    id: attachment.id,
  });
