 * 2. Create a post as memberA
 * 3. As memberA, attach a valid file to the post (expect success)
 * 4. Verify output includes metadata structure (filename, uri, mimeType)
 * 5. As memberB, attempt to attach file to memberA's post (expect permission-denied error)
 * 6. Attempt to attach file to a non-existent post (expect error)
 * 7. Attempt to attach file with invalid metadata (expect validation error)
 */
export async function test_api_discussionboard_test_create_post_attachment_with_valid_and_invalid_data(
