  TestValidator.equals("file_uri updated")(updated.file_uri)(updatedFileUri);
  TestValidator.equals("mime_type updated")(updated.mime_type)(updatedMimeType);

  // 5. As non-owner, attempt update (should fail - permission denied)
  await TestValidator.error("permission denied for non-owner")(
    async () =>
      await api.functional.discussionboard.postAttachments.putById(connection, {
        id: attachment.id,
        body: {
          file_name: "hacked.txt",
          file_uri: "https://attacker.com/steal.txt",
          mime_type: "application/javascript",
        } as IDiscussionboardPostAttachment.IUpdate,
      })
  );

  // 6. Invalid MIME type (should fail - validation error)
  await TestValidator.error("invalid MIME type")(
    async () =>
      await api.functional.discussionboard.postAttachments.putById(connection, {
        id: attachment.id,
        body: {
          file_name: "bad.mime",
          file_uri: "https://example.com/bad.mime",
          mime_type: "not_a/type",
        } as IDiscussionboardPostAttachment.IUpdate,
      })
  );

  // 7. Invalid attachment ID (should fail - not found/validation error)
  await TestValidator.error("not found: invalid id")(
