          mime_type: "text/plain",
        } as IDiscussionboardPostAttachment.IUpdate,
      })
  );

  /* Skipped: update with non-existent fields (impossible at compile time)
   * Skipped: update after soft-delete (no delete/restore endpoint/flag in DTO)
   * Skipped: admin/mod role escalation scenarios (not exposed)
   */
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
